import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuction } from '../hooks/useAuction';
import { AuctionStatus, AuctionSetup } from '../types';
import { Play, Calendar, History, ArrowRight, Shield, Trophy, Users } from 'lucide-react';
import { db } from '../firebase';

const AuctionCard: React.FC<{ auction: AuctionSetup, navigate: (path: string) => void, getStatusBadge: (status: string) => React.Node }> = ({ auction, navigate, getStatusBadge }) => {
    const [teamCount, setTeamCount] = useState<number | null>(null);

    useEffect(() => {
        let mounted = true;
        const fetchCount = async () => {
            if (!auction.id) return;
            try {
                const snap = await db.collection('auctions').doc(auction.id).collection('teams').get();
                if (mounted) setTeamCount(snap.size);
            } catch (e) { console.error("Error fetching team count", e); }
        };
        fetchCount();
        return () => { mounted = false; };
    }, [auction.id]);

    const isRegOpen = auction.registrationConfig?.isEnabled;
    const isPublicReg = auction.registrationConfig?.isPublic ?? true; // Default to true if field missing

    return (
        <div className="bg-secondary border border-accent rounded-xl p-6 hover:border-highlight transition-all flex flex-col relative overflow-hidden group">
            {getStatusBadge(auction.status)}
            <div className="flex justify-between items-start mb-2 mt-2">
                <h3 className="text-xl font-bold text-white">{auction.title}</h3>
                <button onClick={() => navigate(`/auction/${auction.id}`)} className="bg-white/10 hover:bg-white/20 text-white text-xs px-3 py-1 rounded">View Room</button>
            </div>
            <div className="text-text-secondary text-sm mb-4 flex items-center gap-2">
                {(isRegOpen && isPublicReg) ? <span className="text-green-400 font-bold text-[10px] uppercase border border-green-500/30 bg-green-500/10 px-2 py-0.5 rounded">Reg Open</span> : (isRegOpen && !isPublicReg) ? <span className="text-blue-400 font-bold text-[10px] uppercase border border-blue-500/30 bg-blue-500/10 px-2 py-0.5 rounded">Private Reg</span> : <span className="text-gray-500 font-bold text-[10px] uppercase border border-gray-500/30 bg-gray-500/10 px-2 py-0.5 rounded">Reg Closed</span>}
                <span className="text-gray-600">•</span>
                <span>{teamCount !== null ? teamCount : '-'} / {auction.totalTeams} Teams</span>
            </div>
            <div className="mt-auto pt-4 border-t border-gray-700 flex justify-between items-center text-xs text-text-secondary">
                <span>Starts: {auction.date || 'TBA'}</span>
                <div className="flex gap-2">
                <span className="bg-accent px-2 py-1 rounded text-white">{auction.sport}</span>
                {isRegOpen && isPublicReg && <button onClick={() => navigate(`/auction/${auction.id}/register`)} className="text-highlight hover:underline font-bold">Register Player</button>}
                </div>
            </div>
        </div>
    );
};

const LandingPage: React.FC = () => {
  const { state } = useAuction();
  const navigate = useNavigate();
  const [upcomingAuctions, setUpcomingAuctions] = useState<AuctionSetup[]>([]);
  const [pastAuctions, setPastAuctions] = useState<AuctionSetup[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
      setLoading(true);
      const unsubscribe = db.collection('auctions').onSnapshot((snapshot) => {
          const data = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as AuctionSetup));
          data.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
          const active = data.filter(a => { const s = (a.status || '').toUpperCase(); return s === 'DRAFT' || s === 'LIVE' || s === 'NOT_STARTED' || s === 'IN_PROGRESS'; });
          const past = data.filter(a => { const s = (a.status || '').toUpperCase(); return s === 'COMPLETED' || s === 'FINISHED'; });
          setUpcomingAuctions(active);
          setPastAuctions(past);
          setLoading(false);
      }, (error: any) => { setLoading(false); });
      return () => unsubscribe();
  }, []);

  const getStatusBadge = (status: string) => {
      const s = (status || '').toUpperCase();
      if (s === 'IN_PROGRESS' || s === 'LIVE') return <div className="absolute top-0 right-0 bg-red-600 text-white text-xs font-bold px-3 py-1 animate-pulse">LIVE NOW</div>;
      if (s === 'NOT_STARTED') return <div className="absolute top-0 right-0 bg-green-600 text-white text-xs font-bold px-3 py-1">READY TO START</div>;
      return null;
  };

  return (
    <div className="min-h-screen bg-primary flex flex-col font-sans">
      <nav className="border-b border-accent bg-secondary/50 backdrop-blur-md sticky top-0 z-50">
        <div className="container mx-auto px-6 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            {/* LOGO FRAME IN NAVBAR */}
            <div className="w-12 h-12 bg-black rounded-xl border-2 border-highlight p-1.5 shadow-lg flex items-center justify-center overflow-hidden">
                {state.systemLogoUrl ? (
                    <img src={state.systemLogoUrl} className="max-w-full max-h-full object-contain" alt="SM Sports" />
                ) : (
                    <Trophy className="w-full h-full text-highlight" />
                )}
            </div>
            <span className="text-2xl font-bold text-white tracking-wider">SM SPORTS</span>
          </div>
          <div className="flex items-center gap-4">
            <Link to="/auth" className="text-text-secondary hover:text-white transition-colors text-sm font-semibold">Team Login</Link>
            <Link to="/auth" className="bg-highlight hover:bg-teal-400 text-primary font-bold py-2 px-5 rounded-lg transition-all shadow-lg shadow-highlight/20 text-sm">Dashboard</Link>
          </div>
        </div>
      </nav>

      <header className="relative overflow-hidden py-20 lg:py-32">
        <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-teal-900/20 via-primary to-primary"></div>
        <div className="container mx-auto px-6 relative z-10 text-center">
          <div className="inline-block mb-4 px-3 py-1 rounded-full bg-accent/50 border border-accent text-highlight text-xs font-bold tracking-widest uppercase">The Future of Sports Bidding</div>
          <h1 className="text-5xl md:text-7xl font-extrabold text-white mb-6 tracking-tight">Manage Your <br/><span className="text-transparent bg-clip-text bg-gradient-to-r from-highlight to-teal-200">Cricket Auctions</span><br/> Professionally</h1>
          <p className="text-lg text-text-secondary max-w-2xl mx-auto mb-10 leading-relaxed">Experience the thrill of a real-time auction room. Organize players, manage team budgets, and bid live with our advanced auction platform designed for sports enthusiasts.</p>
          <div className="flex flex-col sm:flex-row justify-center gap-4">
            {/* Redirect to registration flow directly */}
            <Link to="/auth?tab=admin&mode=register" className="flex items-center justify-center bg-white text-primary font-bold py-4 px-8 rounded-xl hover:bg-gray-100 transition-all shadow-xl"><Play className="w-5 h-5 mr-2 fill-current" /> Create Auction</Link>
          </div>
        </div>
      </header>

      <section className="py-20 bg-secondary/30 border-t border-accent/50">
        <div className="container mx-auto px-6">
          <div className="flex items-center justify-between mb-10"><h2 className="text-3xl font-bold text-white">Auction Center</h2></div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="flex flex-col gap-4">
               <h4 className="text-sm font-bold text-text-secondary uppercase tracking-wider flex items-center"><Calendar className="w-4 h-4 mr-2" /> Live & Upcoming</h4>
               {loading ? <div className="text-text-secondary text-sm animate-pulse">Loading upcoming events...</div> : upcomingAuctions.length > 0 ? upcomingAuctions.map(auction => <AuctionCard key={auction.id} auction={auction} navigate={navigate} getStatusBadge={getStatusBadge} />) : <div className="bg-secondary/50 border border-dashed border-gray-700 rounded-xl p-6 text-center text-text-secondary text-sm">No upcoming auctions scheduled.</div>}
            </div>
            <div className="flex flex-col gap-4">
               <h4 className="text-sm font-bold text-text-secondary uppercase tracking-wider flex items-center"><History className="w-4 h-4 mr-2" /> Past Results</h4>
               {loading ? <div className="text-text-secondary text-sm animate-pulse">Loading results...</div> : pastAuctions.length > 0 ? pastAuctions.map(auction => <div key={auction.id} className="bg-secondary border border-accent rounded-xl p-6 opacity-80 hover:opacity-100 transition-all group"><h3 className="text-xl font-bold text-white mb-2">{auction.title}</h3><p className="text-text-secondary text-sm mb-4">Completed {auction.date}</p><div className="mt-auto pt-4 border-t border-gray-700 flex justify-between items-center text-xs text-text-secondary"><span>{auction.sport}</span><button onClick={() => navigate(`/auction/${auction.id}`)} className="text-green-400 hover:text-green-300 cursor-pointer font-bold hover:underline bg-transparent border-none p-0">View Stats</button></div></div>) : <div className="bg-secondary/50 border border-dashed border-gray-700 rounded-xl p-6 text-center text-text-secondary text-sm">No past auction results found.</div>}
            </div>
          </div>
        </div>
      </section>

      <footer id="features" className="bg-secondary border-t border-accent py-12 mt-auto">
        <div className="container mx-auto px-6">
           <div className="grid grid-cols-1 md:grid-cols-4 gap-8 mb-8">
              <div><div className="bg-accent/30 w-12 h-12 rounded-lg flex items-center justify-center mb-4 text-highlight"><Users /></div><h4 className="text-white font-bold mb-2">Team Management</h4><p className="text-text-secondary text-sm">Owners can manage squads, view budgets, and strategize in real-time.</p></div>
              <div><div className="bg-accent/30 w-12 h-12 rounded-lg flex items-center justify-center mb-4 text-highlight"><Trophy /></div><h4 className="text-white font-bold mb-2">Live Bidding</h4><p className="text-text-secondary text-sm">Low latency websocket-like updates powered by Firestore for instant bid reflection.</p></div>
              <div><div className="bg-accent/30 w-12 h-12 rounded-lg flex items-center justify-center mb-4 text-highlight"><Shield /></div><h4 className="text-white font-bold mb-2">Admin Controls</h4><p className="text-text-secondary text-sm">Full control for auctioneers to sell, pass, or reset players instantly.</p></div>
              <div><div className="bg-accent/30 w-12 h-12 rounded-lg flex items-center justify-center mb-4 text-highlight"><Play /></div><h4 className="text-white font-bold mb-2">OBS Integration</h4><p className="text-text-secondary text-sm">Broadcast professional overlays directly to your stream with our dedicated view.</p></div>
           </div>
           <div className="border-t border-gray-700 pt-8 text-center text-text-secondary text-sm">&copy; 2025 SM SPORTS. All rights reserved.</div>
        </div>
      </footer>
    </div>
  );
};

export default LandingPage;

import React, { useState, useEffect } from 'react';
import { Mail, Lock, LogIn, ArrowLeft, Key, Hash, Info, AlertTriangle, User, Chrome, ShieldAlert, ChevronRight, RefreshCw } from 'lucide-react';
import { auth, db } from '../firebase';
import firebase from 'firebase/compat/app';
import { useAuction } from '../hooks/useAuction';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';

const AuthScreen: React.FC = () => {
    const { setUserProfile } = useAuction();
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const [activeTab, setActiveTab] = useState<'team' | 'admin'>('team');

    // Admin State
    const [adminName, setAdminName] = useState('');
    const [adminEmail, setAdminEmail] = useState('');
    const [adminPassword, setAdminPassword] = useState('');
    const [isAdminRegister, setIsAdminRegister] = useState(false);

    // Handle deep linking for tabs/registration
    useEffect(() => {
        const tab = searchParams.get('tab');
        const mode = searchParams.get('mode');

        if (tab === 'admin') {
            setActiveTab('admin');
            if (mode === 'register') {
                setIsAdminRegister(true);
            }
        } else if (tab === 'team') {
            setActiveTab('team');
        }
    }, [searchParams]);

    // Forgot Password State
    const [showForgotPassword, setShowForgotPassword] = useState(false);
    const [resetEmail, setResetEmail] = useState('');
    const [resetMessage, setResetMessage] = useState<string | null>(null);

    // Team State
    const [selectedTeamId, setSelectedTeamId] = useState<string>("");
    const [teamPassword, setTeamPassword] = useState('');

    const [error, setError] = useState<string | null>(null);
    const [isConfigError, setIsConfigError] = useState(false);
    const [configErrorMsg, setConfigErrorMsg] = useState("");
    const [isLoading, setIsLoading] = useState(false);

    const getFriendlyErrorMessage = (err: any) => {
        const code = err.code;
        console.error("Auth Error:", code, err.message);

        if (code === 'auth/configuration-not-found' || code === 'auth/operation-not-allowed') {
            setIsConfigError(true);
            return "Firebase Authentication provider is disabled.";
        }
        if (code === 'auth/admin-restricted-operation') {
            setIsConfigError(true);
            if (activeTab === 'team') {
                setConfigErrorMsg("Anonymous Authentication is disabled.");
                return "Team Login requires Anonymous Auth to be enabled.";
            } else {
                setConfigErrorMsg("Create (sign-up) is disabled.");
                return "Client-side sign-up is disabled.";
            }
        }
        if (code === 'auth/invalid-credential') {
            return "Invalid Credentials. If you are logging in, check your password. If you are new, please Register first.";
        }
        if (code === 'auth/wrong-password') {
            return "Incorrect Password.";
        }
        if (code === 'auth/user-not-found') {
            return "User not found. Please register first.";
        }
        if (code === 'auth/email-already-in-use') {
            return "This email is already currently used by another account.";
        }
        if (code === 'auth/weak-password') {
            return "Password should be at least 6 characters.";
        }
        if (code === 'auth/popup-closed-by-user') {
            return "Sign-in popup was closed.";
        }
        return err.message || "An unknown error occurred.";
    };

    const handleGoogleLogin = async () => {
        setError(null);
        setIsConfigError(false);
        setIsLoading(true);
        try {
            const provider = new firebase.auth.GoogleAuthProvider();
            await auth.signInWithPopup(provider);
            // App.tsx auth listener will handle redirection
        } catch (err: any) {
            setError(getFriendlyErrorMessage(err));
            setIsLoading(false);
        }
    };

    const handlePasswordReset = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!resetEmail) {
            setError("Please enter your email address.");
            return;
        }
        setError(null);
        setIsLoading(true);
        try {
            await auth.sendPasswordResetEmail(resetEmail);
            setResetMessage("Password reset email sent! Check your inbox.");
            setIsLoading(false);
        } catch (err: any) {
            setError(getFriendlyErrorMessage(err));
            setIsLoading(false);
        }
    };

    const handleAdminSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setIsConfigError(false);
        setIsLoading(true);

        try {
            if (auth.currentUser) {
                await auth.signOut();
            }

            if (isAdminRegister) {
                if (!adminName.trim()) {
                    throw new Error("Full Name is required for registration.");
                }
                const userCredential = await auth.createUserWithEmailAndPassword(adminEmail, adminPassword);
                if (userCredential.user) {
                    await userCredential.user.updateProfile({
                        displayName: adminName
                    });
                }
            } else {
                await auth.signInWithEmailAndPassword(adminEmail, adminPassword);
            }
        } catch (err: any) {
            setError(getFriendlyErrorMessage(err));
            setIsLoading(false);
        }
    };

    const handleTeamSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setIsConfigError(false);
        setIsLoading(true);

        try {
            const auctionsSnapshot = await db.collection('auctions').get();

            if (auctionsSnapshot.empty) {
                throw new Error("No auctions found.");
            }

            let matchedTeam: any = null;
            let auctionId: string = "";

            for (const doc of auctionsSnapshot.docs) {
                const teamQuery = await doc.ref.collection('teams').where('id', '==', selectedTeamId).limit(1).get();
                if (!teamQuery.empty) {
                    matchedTeam = teamQuery.docs[0].data();
                    auctionId = doc.id;
                    break;
                }
            }

            if (!matchedTeam) {
                throw new Error("Team ID not found.");
            }

            if (matchedTeam.password && matchedTeam.password !== teamPassword) {
                throw new Error("Incorrect Password.");
            }

            const sessionData = {
                role: 'TEAM_OWNER',
                teamId: selectedTeamId,
                auctionId: auctionId
            };
            localStorage.setItem('sm_sports_team_session', JSON.stringify(sessionData));

            if (auth.currentUser) {
                await auth.signOut();
            }

            await auth.signInAnonymously();
            navigate(`/auction/${auctionId}`);

        } catch (err: any) {
            setError(getFriendlyErrorMessage(err));
            setIsLoading(false);
        }
    }

    return (
        <div className="min-h-screen bg-primary font-sans flex items-center justify-center p-4 bg-[url('https://images.unsplash.com/photo-1531415074968-036ba1b575da?q=80&w=2067&auto=format&fit=crop')] bg-cover bg-center bg-no-repeat relative">
            <div className="absolute inset-0 bg-primary/90 backdrop-blur-sm"></div>

            <div className="w-full max-w-md relative z-10 flex flex-col items-center">
                <div className="w-full">
                    <Link to="/" className="inline-flex items-center text-text-secondary hover:text-white mb-6 transition-colors">
                        <ArrowLeft className="w-4 h-4 mr-2" /> Back to Home
                    </Link>

                    <div className="text-center mb-8">
                        <h1 className="text-5xl font-bold text-highlight mb-2 tracking-tighter">🏏 SM SPORTS</h1>
                        <p className="text-text-secondary uppercase tracking-[0.3em] text-[10px] font-black opacity-60">Your Streaming Partner</p>
                    </div>

                    <div className="bg-secondary/80 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-accent/30 overflow-hidden relative group">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-highlight/5 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl"></div>

                        {/* Tabs */}
                        <div className="flex mb-8 bg-primary/50 rounded-xl p-1.5 border border-white/5">
                            <button 
                                onClick={() => { setActiveTab('team'); setError(null); setIsConfigError(false); setShowForgotPassword(false); }}
                                className={`flex-1 py-3 rounded-lg text-xs font-black uppercase tracking-wider transition-all duration-300 ${activeTab === 'team' ? 'bg-highlight text-primary shadow-xl' : 'text-text-secondary hover:text-white'}`}
                            >
                                Team Owner
                            </button>
                            <button 
                                onClick={() => { setActiveTab('admin'); setError(null); setIsConfigError(false); setShowForgotPassword(false); }}
                                className={`flex-1 py-3 rounded-lg text-xs font-black uppercase tracking-wider transition-all duration-300 ${activeTab === 'admin' ? 'bg-highlight text-primary shadow-xl' : 'text-text-secondary hover:text-white'}`}
                            >
                                Admin
                            </button>
                        </div>

                        <h2 className="text-xl font-black text-center text-white mb-8 uppercase tracking-tight">
                            {activeTab === 'team' ? 'Terminal Access' : (showForgotPassword ? 'Security Reset' : (isAdminRegister ? 'Create Account' : 'Authority Login'))}
                        </h2>

                        {/* Critical Config Error Alert */}
                        {isConfigError && (
                            <div className="bg-yellow-500/20 border border-yellow-500 text-yellow-200 p-4 rounded-xl mb-6 text-sm">
                                <div className="flex items-center font-bold mb-2 text-yellow-400">
                                    <AlertTriangle className="w-4 h-4 mr-2" /> SETUP REQUIRED
                                </div>
                                <p className="mb-2 font-semibold">{configErrorMsg || "Configuration missing in Firebase."}</p>
                                <ol className="list-decimal list-inside space-y-1 text-xs text-yellow-100/80">
                                    <li>Go to Firebase Console &gt; <b>Authentication</b></li>
                                    <li>Click <b>Sign-in method</b> tab</li>
                                    {activeTab === 'team' ? (
                                         <li>Enable <b>Anonymous</b> provider.</li>
                                    ) : (
                                         <li>Enable <b>Email/Password</b> and <b>Google</b>.</li>
                                    )}
                                </ol>
                            </div>
                        )}

                        {/* Forgot Password Message */}
                        {resetMessage && (
                            <div className="bg-green-500/20 border border-green-500 text-green-200 p-4 rounded-xl mb-6 text-sm text-center font-bold">
                                {resetMessage}
                            </div>
                        )}

                        {activeTab === 'team' ? (
                            <form onSubmit={handleTeamSubmit} className="space-y-5">
                                <div className="relative group">
                                    <Hash className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary group-focus-within:text-highlight transition-colors" />
                                    <input
                                        type="text"
                                        placeholder="ENTER TEAM ID (T001)"
                                        value={selectedTeamId}
                                        onChange={(e) => setSelectedTeamId(e.target.value.toUpperCase())}
                                        className="w-full bg-primary/80 border border-gray-700/50 rounded-2xl py-4 pl-12 pr-4 text-text-main font-bold focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/30 uppercase tracking-widest transition-all"
                                        required
                                    />
                                </div>

                                <div className="relative group">
                                    <Key className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary group-focus-within:text-highlight transition-colors" />
                                    <input
                                        type="password"
                                        placeholder="ACCESS PASSWORD"
                                        value={teamPassword}
                                        onChange={(e) => setTeamPassword(e.target.value)}
                                        required
                                        className="w-full bg-primary/80 border border-gray-700/50 rounded-2xl py-4 pl-12 pr-4 text-text-main font-bold focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/30 tracking-widest transition-all"
                                    />
                                </div>

                                {error && !isConfigError && <p className="text-red-400 text-xs font-bold text-center bg-red-400/10 py-3 rounded-xl border border-red-500/20">{error}</p>}

                                <button
                                    type="submit"
                                    disabled={isLoading}
                                    className="w-full flex items-center justify-center bg-highlight hover:bg-teal-400 text-primary font-black py-5 px-6 rounded-2xl transition-all duration-500 transform hover:scale-[1.02] disabled:opacity-50 shadow-[0_15px_30px_rgba(56,178,172,0.3)] active:scale-95 uppercase tracking-[0.2em] text-sm"
                                >
                                   {isLoading ? <RefreshCw className="animate-spin w-5 h-5"/> : <><LogIn className="mr-2 h-5 w-5"/> ENTER TERMINAL</>}
                                </button>
                            </form>
                        ) : showForgotPassword ? (
                             <form onSubmit={handlePasswordReset} className="space-y-5 animate-fade-in">
                                <div className="relative">
                                    <Mail className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary" />
                                    <input
                                        type="email"
                                        placeholder="REGISTERED EMAIL"
                                        value={resetEmail}
                                        onChange={(e) => setResetEmail(e.target.value)}
                                        required
                                        className="w-full bg-primary/80 border border-gray-700/50 rounded-2xl py-4 pl-12 pr-4 text-text-main font-bold focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/30 transition-all"
                                    />
                                </div>

                                {error && !isConfigError && <p className="text-red-400 text-xs font-bold text-center bg-red-400/10 py-3 rounded-xl border border-red-500/20">{error}</p>}

                                <button
                                    type="submit"
                                    disabled={isLoading}
                                    className="w-full flex items-center justify-center bg-highlight hover:bg-teal-400 text-primary font-black py-4 px-6 rounded-2xl transition-all uppercase tracking-widest text-xs"
                                >
                                   {isLoading ? 'PROCESSING...' : 'RECOVER ACCESS'}
                                </button>

                                <button
                                    type="button"
                                    onClick={() => setShowForgotPassword(false)}
                                    className="w-full text-[10px] font-black uppercase tracking-[0.3em] text-text-secondary hover:text-white"
                                >
                                    Return to Authentication
                                </button>
                             </form>
                        ) : (
                            <div className="space-y-6 animate-slide-up">
                                 <button
                                    onClick={handleGoogleLogin}
                                    disabled={isLoading}
                                    className="w-full flex items-center justify-center bg-white hover:bg-gray-100 text-gray-900 font-black py-4 px-6 rounded-2xl transition-all shadow-xl mb-4 text-sm active:scale-95"
                                >
