                                            title="Delete Auction"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )) : (
                            <div className="p-8 text-center text-gray-400 italic">
                                {error ? "Could not load auctions." : "No auctions created yet. Click 'Create new auction' to start."}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
      </main>
    </div>
  );
};

