                    const newTeamRef = db.collection('auctions').doc(id).collection('teams').doc(newId);
                    transaction.set(counterRef, { teamCount: nextNum }, { merge: true });
                    transaction.set(newTeamRef, { id: newId, ...teamData });
                    return { id: newId, ...teamData };
