                                            <input required type="number" className="w-full border rounded-lg p-2.5 outline-none focus:ring-2 focus:ring-blue-500" value={editItem.basePrice} onChange={e => setEditItem({...editItem, basePrice: Number(e.target.value)})} />
                                        </div>
                                        <div>
                                            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Max Per Team</label>
                                            <input required type="number" className="w-full border rounded-lg p-2.5 outline-none focus:ring-2 focus:ring-blue-500" value={editItem.maxPerTeam} onChange={e => setEditItem({...editItem, maxPerTeam: Number(e.target.value)})} />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Bid Increment</label>
                                        <input required type="number" className="w-full border rounded-lg p-2.5 outline-none focus:ring-2 focus:ring-blue-500" value={editItem.bidIncrement} onChange={e => setEditItem({...editItem, bidIncrement: Number(e.target.value)})} />
                                    </div>
                                </>
                            )}

                            {activeTab === 'ROLES' && (
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Default Base Price</label>
                                    <input required type="number" className="w-full border rounded-lg p-2.5 outline-none focus:ring-2 focus:ring-blue-500" value={editItem.basePrice} onChange={e => setEditItem({...editItem, basePrice: Number(e.target.value)})} />
                                </div>
                            )}

                            <div className="pt-4">
                                <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl shadow-lg transition-all active:scale-95">
                                    Save Changes
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AuctionManage;

import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../firebase';
import { AuctionSetup, RegistrationConfig, FormField, PlayerRole } from '../types';
import { Upload, Calendar, CheckCircle, AlertTriangle, ArrowUpCircle, FileText, Home, ArrowLeft, Loader2, CreditCard } from 'lucide-react';

const PlayerRegistration: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [auction, setAuction] = useState<AuctionSetup | null>(null);
    const [config, setConfig] = useState<RegistrationConfig | null>(null);
    const [roles, setRoles] = useState<PlayerRole[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState(false);
    const [submitting, setSubmitting] = useState(false);
    const [isRazorpayLoaded, setIsRazorpayLoaded] = useState(false);

    // Fixed Form Data
    const [formData, setFormData] = useState({
        fullName: '',
        playerType: '',
        gender: '',
        mobile: '',
        dob: '',
        captcha: ''
    });

    // Dynamic Form Data (Map field ID -> Value)
    const [customData, setCustomData] = useState<Record<string, any>>({});

    // File Data
    const [profilePic, setProfilePic] = useState<string>('');
    const [paymentScreenshot, setPaymentScreenshot] = useState<string>('');

    const profileInputRef = useRef<HTMLInputElement>(null);
    const paymentInputRef = useRef<HTMLInputElement>(null);

    // Load Razorpay Script
    useEffect(() => {
        const script = document.createElement('script');
        script.src = 'https://checkout.razorpay.com/v1/checkout.js';
        script.async = true;
        script.onload = () => setIsRazorpayLoaded(true);
        document.body.appendChild(script);
        return () => {
            document.body.removeChild(script);
        };
    }, []);

    // Helper to compress images
    const compressImage = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (event) => {
                const img = new Image();
                img.src = event.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const MAX_WIDTH = 800; // Resize to max 800px
                    const MAX_HEIGHT = 800;
                    let width = img.width;
                    let height = img.height;

                    if (width > height) {
                        if (width > MAX_WIDTH) {
                            height *= MAX_WIDTH / width;
                            width = MAX_WIDTH;
                        }
                    } else {
                        if (height > MAX_HEIGHT) {
                            width *= MAX_HEIGHT / height;
                            height = MAX_HEIGHT;
                        }
                    }
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    ctx?.drawImage(img, 0, 0, width, height);
                    // Compress to JPEG with 0.7 quality to reduce size
                    resolve(canvas.toDataURL('image/jpeg', 0.7)); 
                };
                img.onerror = (err) => reject(err);
            };
            reader.onerror = (err) => reject(err);
        });
    };

    // Load Auction Config & Roles
    useEffect(() => {
        const fetchAuction = async () => {
            if (!id) return;
            try {
                // 1. Fetch Auction Doc
                const docSnap = await db.collection('auctions').doc(id).get();
                if (docSnap.exists) {
                    const data = docSnap.data() as AuctionSetup;
                    setAuction(data);
                    if (data.registrationConfig && data.registrationConfig.isEnabled) {
                        setConfig(data.registrationConfig);
                    } else {
                        setError("Registration is currently closed for this auction.");
                    }
                } else {
                    setError("Auction not found.");
                }

                // 2. Fetch Roles (Player Types)
                const roleSnap = await db.collection('auctions').doc(id).collection('roles').get();
                const fetchedRoles = roleSnap.docs.map(d => ({ id: d.id, ...d.data() } as PlayerRole));
                setRoles(fetchedRoles);

            } catch (e) {
                console.error(e);
                setError("Failed to load registration form.");
            } finally {
                setLoading(false);
            }
        };
        fetchAuction();
    }, [id]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleCustomChange = (id: string, value: any) => {
        setCustomData(prev => ({ ...prev, [id]: value }));
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'profile' | 'payment' | 'custom', customFieldId?: string) => {
        const file = e.target.files?.[0];
        if (file) {
            try {
                // Simple validation
                if (!file.type.startsWith('image/')) {
                    alert("Please upload an image file (JPG/PNG).");
                    return;
                }

                // Compress image
                const compressedBase64 = await compressImage(file);

                if (type === 'profile') setProfilePic(compressedBase64);
                else if (type === 'payment') setPaymentScreenshot(compressedBase64);
                else if (customFieldId) {
                    handleCustomChange(customFieldId, compressedBase64); 
                }
            } catch (err) {
                console.error("Image upload error:", err);
                alert("Failed to process image. Please try again.");
            }
        }
    };

    const submitToFirebase = async (paymentId?: string) => {
        if (!id) return;
        setSubmitting(true);
        try {
            const submissionData = {
                ...formData,
                profilePic,
                paymentScreenshot: config?.paymentMethod === 'MANUAL' ? paymentScreenshot : '',
                razorpayPaymentId: paymentId || '',
                ...customData,
                submittedAt: Date.now(),
                status: 'PENDING'
            };

            await db.collection('auctions').doc(id).collection('registrations').add(submissionData);

            setSuccess(true);
            window.scrollTo(0,0);
            setTimeout(() => navigate('/'), 5000);
        } catch (e: any) {
            console.error("Submission Error:", e);
            alert("Database Error: " + e.message);
        } finally {
            setSubmitting(false);
        }
    };

    const handleRazorpayPayment = () => {
        if (!isRazorpayLoaded || !config?.razorpayKey) {
            alert("Payment system not ready. Please refresh.");
            return;
        }

        const options = {
            key: config.razorpayKey,
            amount: config.fee * 100, // amount in paise
            currency: 'INR',
            name: auction?.title || 'SM SPORTS',
            description: 'Player Registration Fee',
            handler: (response: any) => {
                // Payment success!
                submitToFirebase(response.razorpay_payment_id);
            },
            prefill: {
                name: formData.fullName,
                contact: formData.mobile
            },
            theme: {
                color: '#16a34a'
            },
            modal: {
                ondismiss: () => {
                    setSubmitting(false);
                }
            }
        };

        const rzp = new (window as any).Razorpay(options);
        rzp.open();
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!id) return alert("Auction ID missing.");

        const inputCaptcha = formData.captcha.replace(/\s+/g, '').toLowerCase();
        const expectedCaptcha = 'dej7ym'; 
        if (inputCaptcha !== expectedCaptcha) return alert("Incorrect Captcha.");

        if (!profilePic) return alert("Please upload profile picture");

        if (config?.includePayment) {
            if (config.paymentMethod === 'MANUAL' && !paymentScreenshot) return alert("Please upload payment screenshot");
            if (config.paymentMethod === 'RAZORPAY' && (!config.razorpayKey || !isRazorpayLoaded)) return alert("Razorpay is not configured correctly by organizer.");
        }

        if (config?.includePayment && config.paymentMethod === 'RAZORPAY') {
            setSubmitting(true);
            handleRazorpayPayment();
        } else {
            submitToFirebase();
        }
    };

    // --- Dynamic Field Renderer ---
    const renderField = (field: FormField) => {
        const commonClasses = "w-full border border-gray-300 rounded p-2 bg-white outline-none focus:ring-2 focus:ring-green-500 transition-shadow text-gray-900";

        switch (field.type) {
            case 'select':
                return (
                    <select 
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={commonClasses}
                    >
                        <option value="">Select an option</option>
                        {field.options?.map((opt, i) => (
                            <option key={i} value={opt}>{opt}</option>
                        ))}
                    </select>
                );
            case 'file':
                return (
                    <div className="border border-dashed border-gray-300 rounded p-3 text-center cursor-pointer hover:bg-gray-50 flex items-center justify-center text-sm text-gray-500 relative">
                        <input 
                            type="file" 
                            accept="image/*" 
                            required={field.required && !customData[field.id]} 
                            className="absolute inset-0 opacity-0 cursor-pointer" 
                            onChange={(e) => handleFileUpload(e, 'custom', field.id)}
                        />
                         {customData[field.id] ? (
                            <span className="text-green-600 font-bold flex items-center truncate max-w-xs">
                                <CheckCircle className="w-4 h-4 mr-2"/> File Uploaded
                            </span>
                         ) : (
                            <span className="flex items-center"><FileText className="w-4 h-4 mr-2"/> Upload Image</span>
                         )}
                    </div>
                );
            case 'date':
                return (
                    <div className="relative">
                        <input 
                            type="date" 
                            required={field.required}
                            value={customData[field.id] || ''}
                            onChange={(e) => handleCustomChange(field.id, e.target.value)}
                            className={commonClasses}
                        />
                    </div>
                );
            case 'number':
                return (
                    <input 
                        type="number"
                        placeholder={field.placeholder}
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={commonClasses}
                    />
                );
            default:
                return (
                    <input 
                        type="text"
                        placeholder={field.placeholder}
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={commonClasses}
                    />
                );
        }
    };

    if (loading) return <div className="min-h-screen flex items-center justify-center text-gray-900">Loading form...</div>;

    if (error) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
                <div className="bg-white p-8 rounded-lg shadow text-center max-w-md">
                    <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
                    <h2 className="text-xl font-bold text-gray-800 mb-2">Unavailable</h2>
                    <p className="text-gray-600">{error}</p>
                    <button onClick={() => navigate('/')} className="mt-4 text-blue-600 underline">Back to Home</button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 font-sans py-10 px-4 relative">

            {/* Back Button */}
            <div className="max-w-3xl mx-auto mb-6">
                <button 
                    onClick={() => navigate('/')} 
                    className="flex items-center text-gray-600 hover:text-gray-900 transition-colors font-semibold"
                >
                    <ArrowLeft className="w-5 h-5 mr-2" />
                    Back to Home
                </button>
            </div>

            {/* SUCCESS MODAL POPUP */}
            {success && (
                <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fade-in">
                    <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-8 text-center transform transition-all scale-100">
                        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <CheckCircle className="w-10 h-10 text-green-600" />
                        </div>
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">Registration Successful!</h2>
                        <p className="text-gray-600 mb-8">
                            Thank you, <span className="font-bold">{formData.fullName}</span>. Your details have been submitted to the organizer.
                        </p>
                        <div className="space-y-3">
                            <button 
                                onClick={() => navigate('/')}
                                className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-6 rounded-lg shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                            >
                                <Home className="w-5 h-5 mr-2" /> Go to Home
                            </button>
                            <p className="text-xs text-gray-400">Redirecting automatically in 5 seconds...</p>
                        </div>
                    </div>
                </div>
            )}

            <div className={`max-w-3xl mx-auto bg-white shadow-xl rounded-xl overflow-hidden border border-gray-200 ${success ? 'blur-sm pointer-events-none' : ''}`}>

                {/* Header Section */}
                <div className="text-center p-8 pb-4">
                    {config?.bannerUrl && (
                        <img src={config.bannerUrl} alt="Logo" className="h-24 mx-auto mb-6 drop-shadow-md" />
                    )}
                    <h1 className="text-2xl font-bold text-gray-800 mb-2">Player Registration Form - {auction?.title}</h1>

                    {/* Terms */}
                    <div className="mt-6 text-sm text-gray-600 bg-yellow-50 p-4 rounded-lg border border-yellow-100 text-left">
                        <p className="font-bold underline mb-2">Terms & Conditions:</p>
                        <ul className="list-disc list-inside space-y-1">
                            {config?.terms.split('\n').map((term, i) => (
                                <li key={i}>{term}</li>
                            ))}
                        </ul>
                    </div>

                    {/* Manual UPI Section */}
                    {config?.includePayment && config.paymentMethod === 'MANUAL' && (
                        <div className="mt-8 bg-zinc-50 border border-zinc-200 p-6 rounded-2xl animate-fade-in">
                            <p className="text-[10px] font-black uppercase tracking-widest text-zinc-400 mb-4 flex items-center justify-center gap-2">
                                <QrCode className="w-4 h-4"/> Manual Payment Instructions
                            </p>
                            <p className="text-sm font-semibold text-zinc-900">{config?.upiName}</p>
                            <p className="text-xl font-black text-blue-600 mb-4 font-mono">{config?.upiId}</p>
                            {config?.qrCodeUrl && (
                                <div className="flex justify-center">
                                    <div className="bg-white p-4 rounded-3xl shadow-xl border border-zinc-200 group relative overflow-hidden">
                                        <img src={config.qrCodeUrl} alt="UPI QR" className="w-44 h-44 object-contain" />
                                    </div>
                                </div>
                            )}
                            <div className="mt-4 p-3 bg-blue-50 text-blue-700 text-xs font-bold rounded-xl border border-blue-100">
                                Scan the QR code to pay ₹{config.fee}. You MUST upload the screenshot below to complete registration.
                            </div>
                        </div>
                    )}

                    {/* Razorpay Info Header */}
                    {config?.includePayment && config.paymentMethod === 'RAZORPAY' && (
                        <div className="mt-8 bg-green-50 border border-green-200 p-6 rounded-2xl animate-fade-in flex flex-col items-center">
                            <div className="w-12 h-12 bg-green-600 text-white rounded-2xl flex items-center justify-center mb-3 shadow-lg">
                                <CreditCard className="w-6 h-6" />
                            </div>
                            <h3 className="font-black text-green-800 uppercase tracking-tighter text-lg">Secure Auto Payment</h3>
                            <p className="text-xs text-green-600 font-bold mb-1">Registration Fee: ₹{config.fee}</p>
                            <p className="text-[10px] text-green-500 max-w-xs leading-tight">
                                Pay securely using Razorpay (Cards, UPI, Netbanking). Your registration will be instantly processed after payment.
                            </p>
                        </div>
                    )}
                </div>

                {/* Form Section */}
                <form onSubmit={handleSubmit} className="p-8 pt-4">
                    <div className="space-y-6">
                        {/* Personal Info */}
                        <div className="border border-gray-200 rounded-lg p-5">
                            <h3 className="text-sm font-bold text-gray-800 mb-4 border-b pb-2">Personal Information</h3>
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Full name <span className="text-red-500">*</span></label>
                                    <input required name="fullName" type="text" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 focus:ring-2 focus:ring-green-500 outline-none text-gray-900" />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Profile pic <span className="text-red-500">*</span></label>
                                    <div 
                                        onClick={() => profileInputRef.current?.click()}
                                        className="border border-dashed border-gray-300 rounded p-3 text-center cursor-pointer hover:bg-gray-50 flex items-center justify-center text-sm text-gray-500"
                                    >
                                        <input ref={profileInputRef} type="file" accept="image/*" className="hidden" onChange={e => handleFileUpload(e, 'profile')} />
                                        {profilePic ? <span className="text-green-600 font-bold flex items-center"><CheckCircle className="w-4 h-4 mr-2"/> Image Selected</span> : <span>Drag & Drop your files or <span className="underline">Browse</span></span>}
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Player type <span className="text-red-500">*</span></label>
                                    <select required name="playerType" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 bg-white outline-none text-gray-900">
                                        <option value="">Select an option</option>
                                        {roles.length > 0 ? (
                                            roles.map(role => (
                                                <option key={role.id} value={role.name}>{role.name}</option>
                                            ))
                                        ) : (
                                            <>
                                                <option value="Batsman">Batsman</option>
                                                <option value="Bowler">Bowler</option>
                                                <option value="All Rounder">All Rounder</option>
                                                <option value="Wicket Keeper">Wicket Keeper</option>
                                            </>
                                        )}
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Gender <span className="text-red-500">*</span></label>
                                    <select required name="gender" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 bg-white outline-none text-gray-900">
                                        <option value="">Select an option</option>
                                        <option value="Male">Male</option>
                                        <option value="Female">Female</option>
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Mobile <span className="text-red-500">*</span> <span className="text-xs text-gray-400 float-right">Enter WhatsApp number</span></label>
                                    <input required name="mobile" type="tel" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 outline-none text-gray-900" />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Date of birth <span className="text-red-500">*</span></label>
                                    <div className="relative">
                                        <input required name="dob" type="date" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 outline-none text-gray-900" />
                                        <Calendar className="absolute right-3 top-2.5 w-4 h-4 text-gray-400 pointer-events-none" />
                                    </div>
                                </div>

                                {/* Conditionally Render Manual Payment Upload */}
                                {config?.includePayment && config.paymentMethod === 'MANUAL' && (
                                    <div className="animate-fade-in">
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Screenshot of Successful Payment (₹{config?.fee}) <span className="text-red-500">*</span></label>
                                        <div 
                                            onClick={() => paymentInputRef.current?.click()}
                                            className="border border-dashed border-gray-300 rounded p-3 text-center cursor-pointer hover:bg-gray-50 flex items-center justify-center text-sm text-gray-500"
                                        >
                                            <input ref={paymentInputRef} type="file" accept="image/*" className="hidden" onChange={e => handleFileUpload(e, 'payment')} />
                                            {paymentScreenshot ? <span className="text-green-600 font-bold flex items-center"><CheckCircle className="w-4 h-4 mr-2"/> Image Selected</span> : <span>Drag & Drop your files or <span className="underline">Browse</span></span>}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Dynamic Custom Fields */}
                        {config?.customFields && config.customFields.length > 0 && (
                            <div className="border border-gray-200 rounded-lg p-5">
                                <h3 className="text-sm font-bold text-gray-800 mb-4 border-b pb-2">Other Details</h3>
                                <div className="space-y-4">
                                    {config.customFields.map((field) => (
                                        <div key={field.id}>
                                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                                {field.label} {field.required && <span className="text-red-500">*</span>}
                                            </label>
                                            {renderField(field)}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Captcha */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Captcha <span className="text-red-500">*</span></label>
                            <input 
                                required 
                                type="text" 
                                name="captcha" 
                                onChange={handleInputChange}
                                className="w-full border border-gray-300 rounded p-2 mb-2 outline-none text-gray-900" 
                            />
                            <div className="bg-gray-100 p-2 rounded border border-gray-300 inline-block">
                                <span className="font-mono text-xl tracking-[0.5em] text-gray-600 font-bold italic line-through decoration-wavy decoration-red-400">de j 7ym</span>
                            </div>
                        </div>

                        <button 
                            type="submit" 
                            disabled={submitting}
                            className={`w-full bg-[#65a30d] hover:bg-[#4d7c0f] text-white font-black py-4 rounded-xl shadow-xl transition-all flex items-center justify-center gap-3 active:scale-95 ${submitting ? 'opacity-70 cursor-wait' : ''}`}
                        >
                            {submitting ? (
                                <>
                                    <Loader2 className="w-5 h-5 animate-spin"/> 
                                    {config?.paymentMethod === 'RAZORPAY' ? 'PROCESSING PAYMENT...' : 'SUBMITTING...'}
                                </>
                            ) : (
                                <>
                                    {config?.includePayment && config.paymentMethod === 'RAZORPAY' ? (
                                        <><CreditCard className="w-5 h-5"/> PAY ₹{config.fee} & REGISTER</>
                                    ) : (
                                        'SUBMIT REGISTRATION'
                                    )}
                                </>
                            )}
                        </button>
                    </div>
                </form>

                {/* Footer Disclaimer */}
                <div className="p-6 bg-gray-50 border-t border-gray-200 text-xs text-gray-600 leading-relaxed">
                    <p className="font-bold mb-2">Important Disclaimer</p>
                    <p className="mb-2">- SM SPORTS is a platform for auction organizers to put their player auction online.</p>
                    <p className="mb-2">- Before registering for an auction, please carefully review all auction details...</p>
                    <p className="font-bold mt-2">Proceed with caution and at your own risk.</p>

                    <div className="text-center mt-8">
                        <p className="font-bold text-gray-800">Registration System Provided by</p>
                        <div className="w-12 h-12 bg-[#38b2ac] text-white font-black flex items-center justify-center rounded mx-auto mt-2 text-xs shadow-lg">
                            SM
                        </div>
                        <p className="font-bold text-gray-800 mt-1">SM SPORTS</p>
                        <p className="text-gray-400 mt-2">© 2025. All rights reserved</p>
                    </div>
                </div>
            </div>

            {/* Scroll to Top Button */}
            <button onClick={() => window.scrollTo({top: 0, behavior: 'smooth'})} className="fixed bottom-6 right-6 bg-[#84cc16] hover:bg-[#65a30d] text-white p-3 rounded-full shadow-lg transition-all active:scale-90 z-10">
                <ArrowUpCircle className="w-6 h-6" />
            </button>
        </div>
    );
};

export default PlayerRegistration;

import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../firebase';
import { AuctionSetup, RegistrationConfig, FormField, PlayerRole } from '../types';
// Fixed missing QrCode import
import { Upload, Calendar, CheckCircle, AlertTriangle, ArrowUpCircle, FileText, Home, ArrowLeft, Loader2, CreditCard, QrCode } from 'lucide-react';

const PlayerRegistration: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [auction, setAuction] = useState<AuctionSetup | null>(null);
    const [config, setConfig] = useState<RegistrationConfig | null>(null);
    const [roles, setRoles] = useState<PlayerRole[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState(false);
    const [submitting, setSubmitting] = useState(false);
    const [isRazorpayLoaded, setIsRazorpayLoaded] = useState(false);

    // Fixed Form Data
    const [formData, setFormData] = useState({
        fullName: '',
        playerType: '',
        gender: '',
        mobile: '',
        dob: '',
        captcha: ''
    });

    // Dynamic Form Data (Map field ID -> Value)
    const [customData, setCustomData] = useState<Record<string, any>>({});

    // File Data
    const [profilePic, setProfilePic] = useState<string>('');
    const [paymentScreenshot, setPaymentScreenshot] = useState<string>('');

    const profileInputRef = useRef<HTMLInputElement>(null);
    const paymentInputRef = useRef<HTMLInputElement>(null);

    // Load Razorpay Script
    useEffect(() => {
        const script = document.createElement('script');
        script.src = 'https://checkout.razorpay.com/v1/checkout.js';
        script.async = true;
        script.onload = () => setIsRazorpayLoaded(true);
        document.body.appendChild(script);
        return () => {
            document.body.removeChild(script);
        };
    }, []);

    // Helper to compress images
    const compressImage = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (event) => {
                const img = new Image();
                img.src = event.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const MAX_WIDTH = 800; // Resize to max 800px
                    const MAX_HEIGHT = 800;
                    let width = img.width;
                    let height = img.height;

                    if (width > height) {
                        if (width > MAX_WIDTH) {
                            height *= MAX_WIDTH / width;
                            width = MAX_WIDTH;
                        }
                    } else {
                        if (height > MAX_HEIGHT) {
                            width *= MAX_HEIGHT / height;
                            height = MAX_HEIGHT;
                        }
                    }
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    ctx?.drawImage(img, 0, 0, width, height);
                    // Compress to JPEG with 0.7 quality to reduce size
                    resolve(canvas.toDataURL('image/jpeg', 0.7)); 
                };
                img.onerror = (err) => reject(err);
            };
            reader.onerror = (err) => reject(err);
        });
    };

    // Load Auction Config & Roles
    useEffect(() => {
        const fetchAuction = async () => {
            if (!id) return;
            try {
                // 1. Fetch Auction Doc
                const docSnap = await db.collection('auctions').doc(id).get();
                if (docSnap.exists) {
                    const data = docSnap.data() as AuctionSetup;
                    setAuction(data);
                    if (data.registrationConfig && data.registrationConfig.isEnabled) {
                        setConfig(data.registrationConfig);
                    } else {
                        setError("Registration is currently closed for this auction.");
                    }
                } else {
                    setError("Auction not found.");
                }

                // 2. Fetch Roles (Player Types)
                const roleSnap = await db.collection('auctions').doc(id).collection('roles').get();
                const fetchedRoles = roleSnap.docs.map(d => ({ id: d.id, ...d.data() } as PlayerRole));
                setRoles(fetchedRoles);

            } catch (e) {
                console.error(e);
                setError("Failed to load registration form.");
            } finally {
                setLoading(false);
            }
        };
        fetchAuction();
    }, [id]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleCustomChange = (id: string, value: any) => {
        setCustomData(prev => ({ ...prev, [id]: value }));
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'profile' | 'payment' | 'custom', customFieldId?: string) => {
        const file = e.target.files?.[0];
        if (file) {
            try {
                // Simple validation
                if (!file.type.startsWith('image/')) {
                    alert("Please upload an image file (JPG/PNG).");
                    return;
                }

                // Compress image
                const compressedBase64 = await compressImage(file);

                if (type === 'profile') setProfilePic(compressedBase64);
                else if (type === 'payment') setPaymentScreenshot(compressedBase64);
                else if (customFieldId) {
                    handleCustomChange(customFieldId, compressedBase64); 
                }
            } catch (err) {
                console.error("Image upload error:", err);
                alert("Failed to process image. Please try again.");
            }
        }
    };

    const submitToFirebase = async (paymentId?: string) => {
        if (!id) return;
        setSubmitting(true);
        try {
            const submissionData = {
                ...formData,
                profilePic,
                paymentScreenshot: config?.paymentMethod === 'MANUAL' ? paymentScreenshot : '',
                razorpayPaymentId: paymentId || '',
                ...customData,
                submittedAt: Date.now(),
                status: 'PENDING'
            };

            await db.collection('auctions').doc(id).collection('registrations').add(submissionData);

            setSuccess(true);
            window.scrollTo(0,0);
            setTimeout(() => navigate('/'), 5000);
        } catch (e: any) {
            console.error("Submission Error:", e);
            alert("Database Error: " + e.message);
        } finally {
            setSubmitting(false);
        }
    };

    const handleRazorpayPayment = () => {
        if (!isRazorpayLoaded || !config?.razorpayKey) {
            alert("Payment system not ready. Please refresh.");
            return;
        }

        const options = {
            key: config.razorpayKey,
            amount: config.fee * 100, // amount in paise
            currency: 'INR',
            name: auction?.title || 'SM SPORTS',
            description: 'Player Registration Fee',
            handler: (response: any) => {
                // Payment success!
                submitToFirebase(response.razorpay_payment_id);
            },
            prefill: {
                name: formData.fullName,
                contact: formData.mobile
            },
            theme: {
                color: '#16a34a'
            },
            modal: {
                ondismiss: () => {
                    setSubmitting(false);
                }
            }
        };

        const rzp = new (window as any).Razorpay(options);
        rzp.open();
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!id) return alert("Auction ID missing.");

        const inputCaptcha = formData.captcha.replace(/\s+/g, '').toLowerCase();
        const expectedCaptcha = 'dej7ym'; 
        if (inputCaptcha !== expectedCaptcha) return alert("Incorrect Captcha.");

        if (!profilePic) return alert("Please upload profile picture");

        if (config?.includePayment) {
            if (config.paymentMethod === 'MANUAL' && !paymentScreenshot) return alert("Please upload payment screenshot");
            if (config.paymentMethod === 'RAZORPAY' && (!config.razorpayKey || !isRazorpayLoaded)) return alert("Razorpay is not configured correctly by organizer.");
        }

        if (config?.includePayment && config.paymentMethod === 'RAZORPAY') {
            setSubmitting(true);
            handleRazorpayPayment();
        } else {
            submitToFirebase();
        }
    };

    // --- Dynamic Field Renderer ---
    const renderField = (field: FormField) => {
        const commonClasses = "w-full border border-gray-300 rounded p-2 bg-white outline-none focus:ring-2 focus:ring-green-500 transition-shadow text-gray-900";

        switch (field.type) {
            case 'select':
                return (
                    <select 
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={commonClasses}
                    >
                        <option value="">Select an option</option>
                        {field.options?.map((opt, i) => (
                            <option key={i} value={opt}>{opt}</option>
                        ))}
                    </select>
                );
            case 'file':
                return (
                    <div className="border border-dashed border-gray-300 rounded p-3 text-center cursor-pointer hover:bg-gray-50 flex items-center justify-center text-sm text-gray-500 relative">
                        <input 
                            type="file" 
                            accept="image/*" 
                            required={field.required && !customData[field.id]} 
                            className="absolute inset-0 opacity-0 cursor-pointer" 
                            onChange={(e) => handleFileUpload(e, 'custom', field.id)}
                        />
                         {customData[field.id] ? (
                            <span className="text-green-600 font-bold flex items-center truncate max-w-xs">
                                <CheckCircle className="w-4 h-4 mr-2"/> File Uploaded
                            </span>
                         ) : (
                            <span className="flex items-center"><FileText className="w-4 h-4 mr-2"/> Upload Image</span>
                         )}
                    </div>
                );
            case 'date':
                return (
                    <div className="relative">
                        <input 
                            type="date" 
                            required={field.required}
                            value={customData[field.id] || ''}
                            onChange={(e) => handleCustomChange(field.id, e.target.value)}
                            className={commonClasses}
                        />
                    </div>
                );
            case 'number':
                return (
                    <input 
                        type="number"
                        placeholder={field.placeholder}
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={commonClasses}
                    />
                );
            default:
                return (
                    <input 
                        type="text"
                        placeholder={field.placeholder}
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={commonClasses}
                    />
                );
        }
    };

    if (loading) return <div className="min-h-screen flex items-center justify-center text-gray-900">Loading form...</div>;

    if (error) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
                <div className="bg-white p-8 rounded-lg shadow text-center max-w-md">
                    <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
                    <h2 className="text-xl font-bold text-gray-800 mb-2">Unavailable</h2>
                    <p className="text-gray-600">{error}</p>
                    <button onClick={() => navigate('/')} className="mt-4 text-blue-600 underline">Back to Home</button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 font-sans py-10 px-4 relative">

            {/* Back Button */}
            <div className="max-w-3xl mx-auto mb-6">
                <button 
                    onClick={() => navigate('/')} 
                    className="flex items-center text-gray-600 hover:text-gray-900 transition-colors font-semibold"
                >
                    <ArrowLeft className="w-5 h-5 mr-2" />
                    Back to Home
                </button>
            </div>

            {/* SUCCESS MODAL POPUP */}
            {success && (
                <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fade-in">
                    <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-8 text-center transform transition-all scale-100">
                        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <CheckCircle className="w-10 h-10 text-green-600" />
                        </div>
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">Registration Successful!</h2>
                        <p className="text-gray-600 mb-8">
                            Thank you, <span className="font-bold">{formData.fullName}</span>. Your details have been submitted to the organizer.
                        </p>
                        <div className="space-y-3">
                            <button 
                                onClick={() => navigate('/')}
                                className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-6 rounded-lg shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                            >
                                <Home className="w-5 h-5 mr-2" /> Go to Home
                            </button>
                            <p className="text-xs text-gray-400">Redirecting automatically in 5 seconds...</p>
                        </div>
                    </div>
                </div>
            )}

            <div className={`max-w-3xl mx-auto bg-white shadow-xl rounded-xl overflow-hidden border border-gray-200 ${success ? 'blur-sm pointer-events-none' : ''}`}>

                {/* Header Section */}
                <div className="text-center p-8 pb-4">
                    {config?.bannerUrl && (
                        <img src={config.bannerUrl} alt="Logo" className="h-24 mx-auto mb-6 drop-shadow-md" />
                    )}
                    <h1 className="text-2xl font-bold text-gray-800 mb-2">Player Registration Form - {auction?.title}</h1>

                    {/* Terms */}
                    <div className="mt-6 text-sm text-gray-600 bg-yellow-50 p-4 rounded-lg border border-yellow-100 text-left">
                        <p className="font-bold underline mb-2">Terms & Conditions:</p>
                        <ul className="list-disc list-inside space-y-1">
                            {config?.terms.split('\n').map((term, i) => (
                                <li key={i}>{term}</li>
                            ))}
                        </ul>
                    </div>

                    {/* Manual UPI Section */}
                    {config?.includePayment && config.paymentMethod === 'MANUAL' && (
                        <div className="mt-8 bg-zinc-50 border border-zinc-200 p-6 rounded-2xl animate-fade-in">
                            <p className="text-[10px] font-black uppercase tracking-widest text-zinc-400 mb-4 flex items-center justify-center gap-2">
                                <QrCode className="w-4 h-4"/> Manual Payment Instructions
                            </p>
                            <p className="text-sm font-semibold text-zinc-900">{config?.upiName}</p>
                            <p className="text-xl font-black text-blue-600 mb-4 font-mono">{config?.upiId}</p>
                            {config?.qrCodeUrl && (
                                <div className="flex justify-center">
                                    <div className="bg-white p-4 rounded-3xl shadow-xl border border-zinc-200 group relative overflow-hidden">
                                        <img src={config.qrCodeUrl} alt="UPI QR" className="w-44 h-44 object-contain" />
                                    </div>
                                </div>
                            )}
                            <div className="mt-4 p-3 bg-blue-50 text-blue-700 text-xs font-bold rounded-xl border border-blue-100">
                                Scan the QR code to pay ₹{config.fee}. You MUST upload the screenshot below to complete registration.
                            </div>
                        </div>
                    )}

                    {/* Razorpay Info Header */}
                    {config?.includePayment && config.paymentMethod === 'RAZORPAY' && (
                        <div className="mt-8 bg-green-50 border border-green-200 p-6 rounded-2xl animate-fade-in flex flex-col items-center">
                            <div className="w-12 h-12 bg-green-600 text-white rounded-2xl flex items-center justify-center mb-3 shadow-lg">
                                <CreditCard className="w-6 h-6" />
                            </div>
                            <h3 className="font-black text-green-800 uppercase tracking-tighter text-lg">Secure Auto Payment</h3>
                            <p className="text-xs text-green-600 font-bold mb-1">Registration Fee: ₹{config.fee}</p>
                            <p className="text-[10px] text-green-500 max-w-xs leading-tight">
                                Pay securely using Razorpay (Cards, UPI, Netbanking). Your registration will be instantly processed after payment.
                            </p>
                        </div>
                    )}
                </div>

                {/* Form Section */}
                <form onSubmit={handleSubmit} className="p-8 pt-4">
                    <div className="space-y-6">
                        {/* Personal Info */}
                        <div className="border border-gray-200 rounded-lg p-5">
                            <h3 className="text-sm font-bold text-gray-800 mb-4 border-b pb-2">Personal Information</h3>
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Full name <span className="text-red-500">*</span></label>
                                    <input required name="fullName" type="text" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 focus:ring-2 focus:ring-green-500 outline-none text-gray-900" />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Profile pic <span className="text-red-500">*</span></label>
                                    <div 
                                        onClick={() => profileInputRef.current?.click()}
                                        className="border border-dashed border-gray-300 rounded p-3 text-center cursor-pointer hover:bg-gray-50 flex items-center justify-center text-sm text-gray-500"
                                    >
                                        <input ref={profileInputRef} type="file" accept="image/*" className="hidden" onChange={e => handleFileUpload(e, 'profile')} />
                                        {profilePic ? <span className="text-green-600 font-bold flex items-center"><CheckCircle className="w-4 h-4 mr-2"/> Image Selected</span> : <span>Drag & Drop your files or <span className="underline">Browse</span></span>}
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Player type <span className="text-red-500">*</span></label>
                                    <select required name="playerType" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 bg-white outline-none text-gray-900">
                                        <option value="">Select an option</option>
                                        {roles.length > 0 ? (
                                            roles.map(role => (
                                                <option key={role.id} value={role.name}>{role.name}</option>
                                            ))
                                        ) : (
                                            <>
                                                <option value="Batsman">Batsman</option>
                                                <option value="Bowler">Bowler</option>
                                                <option value="All Rounder">All Rounder</option>
                                                <option value="Wicket Keeper">Wicket Keeper</option>
                                            </>
                                        )}
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Gender <span className="text-red-500">*</span></label>
                                    <select required name="gender" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 bg-white outline-none text-gray-900">
                                        <option value="">Select an option</option>
                                        <option value="Male">Male</option>
                                        <option value="Female">Female</option>
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Mobile <span className="text-red-500">*</span> <span className="text-xs text-gray-400 float-right">Enter WhatsApp number</span></label>
                                    <input required name="mobile" type="tel" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 outline-none text-gray-900" />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Date of birth <span className="text-red-500">*</span></label>
                                    <div className="relative">
                                        <input required name="dob" type="date" onChange={handleInputChange} className="w-full border border-gray-300 rounded p-2 outline-none text-gray-900" />
                                        <Calendar className="absolute right-3 top-2.5 w-4 h-4 text-gray-400 pointer-events-none" />
                                    </div>
                                </div>

                                {/* Conditionally Render Manual Payment Upload */}
                                {config?.includePayment && config.paymentMethod === 'MANUAL' && (
                                    <div className="animate-fade-in">
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Screenshot of Successful Payment (₹{config?.fee}) <span className="text-red-500">*</span></label>
                                        <div 
                                            onClick={() => paymentInputRef.current?.click()}
                                            className="border border-dashed border-gray-300 rounded p-3 text-center cursor-pointer hover:bg-gray-50 flex items-center justify-center text-sm text-gray-500"
                                        >
                                            <input ref={paymentInputRef} type="file" accept="image/*" className="hidden" onChange={e => handleFileUpload(e, 'payment')} />
                                            {paymentScreenshot ? <span className="text-green-600 font-bold flex items-center"><CheckCircle className="w-4 h-4 mr-2"/> Image Selected</span> : <span>Drag & Drop your files or <span className="underline">Browse</span></span>}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Dynamic Custom Fields */}
                        {config?.customFields && config.customFields.length > 0 && (
                            <div className="border border-gray-200 rounded-lg p-5">
                                <h3 className="text-sm font-bold text-gray-800 mb-4 border-b pb-2">Other Details</h3>
                                <div className="space-y-4">
                                    {config.customFields.map((field) => (
                                        <div key={field.id}>
                                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                                {field.label} {field.required && <span className="text-red-500">*</span>}
                                            </label>
                                            {renderField(field)}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Captcha */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Captcha <span className="text-red-500">*</span></label>
                            <input 
                                required 
                                type="text" 
                                name="captcha" 
                                onChange={handleInputChange}
                                className="w-full border border-gray-300 rounded p-2 mb-2 outline-none text-gray-900" 
                            />
                            <div className="bg-gray-100 p-2 rounded border border-gray-300 inline-block">
                                <span className="font-mono text-xl tracking-[0.5em] text-gray-600 font-bold italic line-through decoration-wavy decoration-red-400">de j 7ym</span>
                            </div>
                        </div>

                        <button 
                            type="submit" 
                            disabled={submitting}
                            className={`w-full bg-[#65a30d] hover:bg-[#4d7c0f] text-white font-black py-4 rounded-xl shadow-xl transition-all flex items-center justify-center gap-3 active:scale-95 ${submitting ? 'opacity-70 cursor-wait' : ''}`}
                        >
                            {submitting ? (
                                <>
                                    <Loader2 className="w-5 h-5 animate-spin"/> 
                                    {config?.paymentMethod === 'RAZORPAY' ? 'PROCESSING PAYMENT...' : 'SUBMITTING...'}
                                </>
                            ) : (
                                <>
                                    {config?.includePayment && config.paymentMethod === 'RAZORPAY' ? (
                                        <><CreditCard className="w-5 h-5"/> PAY ₹{config.fee} & REGISTER</>
                                    ) : (
                                        'SUBMIT REGISTRATION'
                                    )}
                                </>
                            )}
                        </button>
                    </div>
                </form>

                {/* Footer Disclaimer */}
                <div className="p-6 bg-gray-50 border-t border-gray-200 text-xs text-gray-600 leading-relaxed">
                    <p className="font-bold mb-2">Important Disclaimer</p>
                    <p className="mb-2">- SM SPORTS is a platform for auction organizers to put their player auction online.</p>
                    <p className="mb-2">- Before registering for an auction, please carefully review all auction details...</p>
                    <p className="font-bold mt-2">Proceed with caution and at your own risk.</p>

                    <div className="text-center mt-8">
                        <p className="font-bold text-gray-800">Registration System Provided by</p>
                        <div className="w-12 h-12 bg-[#38b2ac] text-white font-black flex items-center justify-center rounded mx-auto mt-2 text-xs shadow-lg">
                            SM
                        </div>
                        <p className="font-bold text-gray-800 mt-1">SM SPORTS</p>
                        <p className="text-gray-400 mt-2">© 2025. All rights reserved</p>
                    </div>
                </div>
            </div>

            {/* Scroll to Top Button */}
            <button onClick={() => window.scrollTo({top: 0, behavior: 'smooth'})} className="fixed bottom-6 right-6 bg-[#84cc16] hover:bg-[#65a30d] text-white p-3 rounded-full shadow-lg transition-all active:scale-90 z-10">
                <ArrowUpCircle className="w-6 h-6" />
            </button>
        </div>
    );
};

export default PlayerRegistration;

import React, { useState, useEffect, useMemo } from 'react';
import { useAuction } from '../hooks/useAuction';
import { AuctionStatus, Team, Player, ProjectorLayout, OBSLayout } from '../types';
import TeamStatusCard from '../components/TeamStatusCard';
// Fixed missing LayoutList import
import { Play, Check, X, ArrowLeft, Loader2, RotateCcw, AlertOctagon, DollarSign, Cast, Lock, Unlock, Monitor, ChevronDown, Shuffle, Search, User, Palette, Trophy, Gavel, Wallet, Eye, EyeOff, Clock, Zap, Undo2, RefreshCw, LayoutList } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const LiveAdminPanel: React.FC = () => {
  const { state, sellPlayer, passPlayer, startAuction, undoPlayerSelection, endAuction, resetAuction, resetCurrentPlayer, resetUnsoldPlayers, updateBiddingStatus, toggleSelectionMode, updateTheme, activeAuctionId, placeBid, nextBid, updateSponsorConfig, correctPlayerSale } = useAuction();
  const { teams, players, biddingStatus, playerSelectionMode, categories, maxPlayersPerTeam } = state;
  const navigate = useNavigate();
  const [isProcessing, setIsProcessing] = useState(false);

  // Inline Sell State
  const [isSellingMode, setIsSellingMode] = useState(false);
  const [selectedTeamId, setSelectedTeamId] = useState<string>('');
  const [finalPrice, setFinalPrice] = useState<number>(0);

  // Manual Player Selection State
  const [manualPlayerId, setManualPlayerId] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState(''); // New search state
  const [showUnsold, setShowUnsold] = useState(false); // Toggle to include unsold players

  // Undo State
  const [lastAction, setLastAction] = useState<{playerId: string, type: 'SOLD' | 'UNSOLD', name: string} | null>(null);

  // Sponsor Config Local State (debounce or immediate)
  const [sponsorLoop, setSponsorLoop] = useState(state.sponsorConfig?.loopInterval || 5);

  // Auto-fill price and leader when entering sell mode or when bid updates
  useEffect(() => {
      // 1. Determine Price
      if (state.currentBid !== null && state.currentBid > 0) {
          setFinalPrice(Number(state.currentBid));
      } else if (state.currentPlayerId) {
          // Fallback to Base Price if no bids
          const p = players.find(player => String(player.id) === String(state.currentPlayerId));
          if (p) setFinalPrice(p.basePrice);
      }

      // 2. Determine Team
      if (state.highestBidder) {
          setSelectedTeamId(String(state.highestBidder.id));
      } else if (!isSellingMode) {
          // Reset selection only if we aren't currently editing
          setSelectedTeamId('');
      }
  }, [state.currentBid, state.highestBidder, isSellingMode, state.currentPlayerId, players]);

  // Sync sponsor loop state
  useEffect(() => {
      if(state.sponsorConfig?.loopInterval) setSponsorLoop(state.sponsorConfig.loopInterval);
  }, [state.sponsorConfig]);

  const handleStart = async (specificId?: string) => {
      if (teams.length === 0) {
          alert("Cannot start auction: No teams added. Please go back to Dashboard > Edit Auction > Teams to add teams.");
          return;
      }

      const availablePlayers = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
      if (availablePlayers.length === 0 && !showUnsold) {
          alert("Cannot start auction: No more players available.");
          return;
      }

      setIsProcessing(true);
      // If restarting an unsold player, specificId will be passed.
      const hasNextPlayer = await startAuction(specificId);

      if (!hasNextPlayer && !showUnsold) {
          if (window.confirm("No more players available in the pool.\n\nDo you want to MARK AUCTION AS COMPLETED?")) {
              await endAuction();
          }
      } else {
          // Clear manual selection
          setManualPlayerId('');
          setSearchTerm('');
      }
      setIsProcessing(false);
  }

  const handleResetFull = async () => {
      if(!window.confirm("WARNING: This will reset the auction status to 'Not Started'. It will NOT remove sold players from teams. Proceed?")) return;
      setIsProcessing(true);
      await resetAuction();
      setIsProcessing(false);
  }

  const handleResetPlayer = async () => {
      if(!window.confirm("This will clear the current bid and timer for this player. Proceed?")) return;
      setIsProcessing(true);
      await resetCurrentPlayer();
      setIsProcessing(false);
  }

  const handleCancelSelection = async () => {
      if(!window.confirm("Change Player? This will cancel the current round and allow you to select a different player.")) return;
      setIsProcessing(true);
      await undoPlayerSelection();
      setIsProcessing(false);
  }

  const handleUndoLastAction = async () => {
      if (!lastAction) return;
      if (!window.confirm(`Undo ${lastAction.type} status for ${lastAction.name}? This will return them to the pool.`)) return;

      setIsProcessing(true);
      try {
          await correctPlayerSale(lastAction.playerId, null, 0); // null team, 0 price = reset to pool
          setLastAction(null);
      } catch (e) {
          console.error(e);
          alert("Failed to undo action.");
      } finally {
          setIsProcessing(false);
      }
  }

  const handleResetSingleUnsold = async (playerId: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (!window.confirm("Bring this player back to pool (remove UNSOLD status)?")) return;

      setIsProcessing(true);
      try {
          await correctPlayerSale(playerId, null, 0);
          // If this player was selected in manual dropdown, they will now appear as normal available player
      } catch (e) {
          alert("Failed to reset player.");
      } finally {
          setIsProcessing(false);
      }
  }

  const copyOBSLink = (type: 'transparent' | 'green') => {
      if (!activeAuctionId) return;
      const baseUrl = window.location.href.split('#')[0];
      const route = type === 'green' ? 'obs-green' : 'obs-overlay';
      const url = `${baseUrl}#/${route}/${activeAuctionId}`;
      navigator.clipboard.writeText(url);

      if (type === 'green') {
          alert("PROJECTOR VIEW URL Copied!\n\nOpen this link on the projector screen.");
      } else {
          alert("OBS OVERLAY URL Copied!\n\nPaste this into OBS Browser Source.");
      }
  };

  const handleSellClick = () => {
      setIsSellingMode(true);
  };

  const cancelSell = () => {
      setIsSellingMode(false);
  };

  const confirmSell = async () => {
      if (!selectedTeamId) {
          alert("Please select a team to sell to.");
          return;
      }
      if (finalPrice <= 0) {
          alert("Price must be greater than 0.");
          return;
      }

      setIsProcessing(true);
      const pid = state.currentPlayerId ? String(state.currentPlayerId) : '';
      const pName = players.find(p => String(p.id) === pid)?.name || 'Player';

      try {
          await sellPlayer(selectedTeamId, finalPrice);
          setLastAction({ playerId: pid, type: 'SOLD', name: pName });
          setIsSellingMode(false);
      } catch(e) {
          console.error(e);
          alert("Failed to sell player. Check console.");
      } finally {
          setIsProcessing(false);
      }
  };

  const handlePass = async () => {
      if (window.confirm("Confirm UNSOLD?")) {
          setIsProcessing(true);
          const pid = state.currentPlayerId ? String(state.currentPlayerId) : '';
          const pName = players.find(p => String(p.id) === String(pid))?.name || 'Player';

          await passPlayer();
          setLastAction({ playerId: String(pid), type: 'UNSOLD', name: pName });
          setIsProcessing(false);
      }
  }

  const handleQuickBid = async (teamId: string | number) => {
      try {
          await placeBid(teamId, nextBid);
      } catch (e) {
          console.error(e);
          // Optional: Show toast error
      }
  };

  const updateSponsorVisibility = (target: 'OBS' | 'PROJECTOR') => {
      const current = state.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 };
      const newConfig = {
          ...current,
          showOnOBS: target === 'OBS' ? !current.showOnOBS : current.showOnOBS,
          showOnProjector: target === 'PROJECTOR' ? !current.showOnProjector : current.showOnProjector
      };
      updateSponsorConfig(newConfig);
  };

  const toggleHighlights = () => {
    const current = state.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5, showHighlights: false };
    updateSponsorConfig({ ...current, showHighlights: !current.showHighlights });
  };

  const handleSponsorLoopChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = Number(e.target.value);
      setSponsorLoop(val);
  };

  const saveSponsorLoop = () => {
      const current = state.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 };
      updateSponsorConfig({ ...current, loopInterval: sponsorLoop });
  };

  const selectedPlayerObj = players.find(p => p.id === manualPlayerId);
  const currentPlayer = state.currentPlayerId ? state.players.find(p => String(p.id) === String(state.currentPlayerId)) : null;

  const getControlButtons = () => {
      const isRoundActive = state.status === AuctionStatus.InProgress && state.currentPlayerId;
      const availablePlayersCount = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD').length;
      const isStartDisabled = isProcessing || (state.status === AuctionStatus.NotStarted && (teams.length === 0 || availablePlayersCount === 0));
      const unsoldCount = players.filter(p => p.status === 'UNSOLD').length;

      // Finish Auction Option
      if (availablePlayersCount === 0 && state.status !== AuctionStatus.NotStarted && !isRoundActive) {
          return (
             <div className="space-y-4 animate-fade-in">
                 {unsoldCount > 0 && (
                     <div className="bg-blue-900/30 border border-blue-500/50 p-4 rounded-xl text-center shadow-inner">
                        <h3 className="text-white font-bold text-lg mb-2">Unsold Players Available</h3>
                        <p className="text-gray-300 text-xs mb-4">There are {unsoldCount} unsold players. Do you want to bring them back into the bidding pool?</p>
                        <button 
                            onClick={async () => {
                                if(window.confirm(`Bring back ${unsoldCount} unsold players to the pool?`)) {
                                    setIsProcessing(true);
                                    await resetUnsoldPlayers();
                                    setIsProcessing(false);
                                }
                            }}
                            disabled={isProcessing}
                            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 rounded-lg shadow-lg transition-all active:scale-95 flex items-center justify-center"
                        >
                            {isProcessing ? <Loader2 className="mr-2 h-4 w-4 animate-spin"/> : <RotateCcw className="mr-2 h-4 w-4"/>}
                            BRING BACK UNSOLD ({unsoldCount})
                        </button>
                     </div>
                 )}

                 <div className="bg-green-900/30 border border-green-500/50 p-6 rounded-xl text-center shadow-inner">
                    <Trophy className="w-12 h-12 text-yellow-400 mx-auto mb-3 drop-shadow-lg" />
                    <h3 className="text-white font-bold text-xl mb-2">Auction Completed!</h3>
                    <p className="text-gray-300 text-sm mb-6">All players have been auctioned. You can now finalize the event.</p>
                    <button 
                        onClick={async () => {
                            if(window.confirm("Are you sure you want to finish the auction? This will enable the summary view for all users.")) {
                                setIsProcessing(true);
                                await endAuction();
                                setIsProcessing(false);
                            }
                        }}
                        disabled={isProcessing}
                        className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-4 rounded-lg shadow-lg shadow-green-900/20 transition-all active:scale-95 flex items-center justify-center tracking-wide"
                    >
                        {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : "GENERATE SUMMARY & FINISH"}
                    </button>
                </div>
            </div>
          );
      }

      // 1. ACTIVE ROUND CONTROLS (SOLD / UNSOLD)
      if (isRoundActive) {
          if (isSellingMode) {
              return (
                  <div className="bg-primary/20 p-3 rounded-lg border border-gray-600 animate-fade-in space-y-3">
                      <div className="flex items-center gap-2 mb-2 text-white font-bold border-b border-gray-600 pb-1">
                          <Check className="w-4 h-4 text-green-500" /> Confirm Sale
                      </div>

                      {/* Inline Form */}
                      <div>
                          <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Sold To Team</label>
                          <div className="grid grid-cols-2 gap-1 overflow-y-auto max-h-32 p-1 bg-black/20 rounded">
                              {teams.map(t => (
                                  <button 
                                    key={t.id}
                                    type="button"
                                    onClick={() => setSelectedTeamId(String(t.id))}
                                    className={`px-2 py-1.5 rounded text-[10px] font-bold border transition-all truncate ${selectedTeamId === String(t.id) ? 'bg-green-600 text-white border-green-400' : 'bg-gray-800 text-gray-400 border-gray-700 hover:text-white'}`}
                                  >
                                      {t.name} ({t.budget})
                                  </button>
                              ))}
                          </div>
                      </div>

                      <div>
                          <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Final Price</label>
                          <div className="relative">
                              <DollarSign className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-green-500" />
                              <input 
                                type="number" 
                                value={finalPrice} 
                                onChange={(e) => setFinalPrice(Number(e.target.value))}
                                className="w-full bg-primary border border-gray-600 rounded p-2 pl-8 text-sm text-white font-bold outline-none focus:border-green-500"
                              />
                          </div>
                      </div>

                      <div className="flex gap-2 pt-1">
                          <button 
                            onClick={cancelSell}
                            className="flex-1 bg-gray-600 hover:bg-gray-700 text-white py-2 rounded text-sm font-bold transition-colors"
                          >
                              Cancel
                          </button>
                          <button 
                            onClick={confirmSell}
                            disabled={isProcessing}
                            className="flex-1 bg-green-600 hover:bg-green-700 text-white py-2 rounded text-sm font-bold shadow-lg flex items-center justify-center transition-colors"
                          >
                              {isProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : 'Confirm'}
                          </button>
                      </div>
                  </div>
              );
          }

          return (
              <div className="space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                      <button 
                        onClick={handleSellClick}
                        disabled={isProcessing}
                        className="flex flex-col items-center justify-center bg-green-600 hover:bg-green-700 disabled:bg-gray-700 disabled:text-gray-500 disabled:cursor-not-allowed text-white font-bold py-4 px-2 rounded-lg transition-all shadow-md active:scale-95"
                      >
                          {isProcessing ? <Loader2 className="mb-1 h-6 w-6 animate-spin"/> : <Check className="mb-1 h-6 w-6"/>}
                          {isProcessing ? 'SELLING...' : 'SOLD'}
                      </button>
                      <button 
                        onClick={handlePass}
                        disabled={isProcessing}
                        className="flex flex-col items-center justify-center bg-red-600 hover:bg-red-700 disabled:bg-gray-700 disabled:text-gray-500 disabled:cursor-not-allowed text-white font-bold py-4 px-2 rounded-lg transition-all shadow-md active:scale-95"
                      >
                          {isProcessing ? <Loader2 className="mb-1 h-6 w-6 animate-spin"/> : <X className="mb-1 h-6 w-6"/>}
                          UNSOLD
                      </button>
                  </div>
                  {/* Inline Cancel / Change Player Button */}
                  <button 
                    onClick={handleCancelSelection} 
                    disabled={isProcessing}
                    className="w-full flex items-center justify-center bg-orange-600 hover:bg-orange-700 text-white font-bold py-2 rounded-lg text-xs transition-colors shadow-sm active:scale-95"
                  >
                      <Undo2 className="w-4 h-4 mr-1" /> Change Player / Cancel Round
                  </button>
              </div>
          );
      }

      // 2. NEXT PLAYER SELECTION (Fully Inline Options)
      if (playerSelectionMode === 'MANUAL') {
           let availablePlayers = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
           if (showUnsold) {
               const unsoldList = players.filter(p => p.status === 'UNSOLD');
               availablePlayers = [...availablePlayers, ...unsoldList];
           }

           availablePlayers.sort((a, b) => a.name.localeCompare(b.name));

           const filteredPlayers = availablePlayers.filter(p => 
               p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
               p.category.toLowerCase().includes(searchTerm.toLowerCase())
           );

           return (
               <div className="space-y-3 bg-primary/20 p-3 rounded-lg border border-gray-600">
                   <div>
                       <div className="flex justify-between items-center mb-1">
                           <label className="block text-[10px] text-text-secondary uppercase font-bold">Select Next Player</label>
                           <label className="flex items-center text-[10px] text-yellow-400 cursor-pointer">
                               <input type="checkbox" checked={showUnsold} onChange={(e) => setShowUnsold(e.target.checked)} className="mr-1 accent-yellow-500" />
                               Include Unsold
                           </label>
                       </div>

                       {/* Inline Search Input */}
                       <div className="relative mb-2">
                           <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
                           <input 
                                type="text"
                                className="w-full bg-gray-900 border border-gray-700 rounded p-1.5 pl-7 text-xs text-white focus:border-highlight outline-none"
                                placeholder="Search player name..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                           />
                       </div>

                       {/* Options listed directly as per instructions */}
                       <div className="max-h-40 overflow-y-auto border border-gray-700 rounded bg-gray-900 custom-scrollbar mb-2">
                            {filteredPlayers.length > 0 ? filteredPlayers.map(p => (
                                <div 
                                    key={p.id}
                                    onClick={() => setManualPlayerId(String(p.id))}
                                    className={`p-2 text-[10px] cursor-pointer border-b border-gray-800 last:border-0 hover:bg-highlight/10 transition-colors ${manualPlayerId === String(p.id) ? 'bg-highlight/20 text-highlight font-bold' : 'text-gray-300'}`}
                                >
                                    <div className="flex justify-between items-center">
                                        <span>{p.name} <span className="opacity-60">({p.category})</span></span>
                                        <span className="font-mono">{p.basePrice}</span>
                                    </div>
                                    {p.status === 'UNSOLD' && <span className="text-red-400 text-[8px] font-bold uppercase">Unsold</span>}
                                </div>
                            )) : (
                                <div className="p-4 text-center text-gray-500 text-[10px] italic">No players found</div>
                            )}
                       </div>
                   </div>

                   <button 
                     onClick={() => handleStart(manualPlayerId)} 
                     disabled={isStartDisabled || !manualPlayerId}
                     className={`w-full flex items-center justify-center font-bold py-3 px-4 rounded-lg transition-colors duration-300 shadow-lg shadow-highlight/20 active:scale-95
                         ${isStartDisabled || !manualPlayerId
                             ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                             : 'bg-highlight hover:bg-teal-500 text-primary'}`
                     }
                   >
                       {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Play className="mr-2 h-5 w-5"/>} 
                       {manualPlayerId && players.find(p => String(p.id) === manualPlayerId)?.status === 'UNSOLD' ? 'Re-Auction Player' : 'Start Bidding'}
                   </button>
               </div>
           );
      }

      // AUTO MODE
      return (
          <button 
            onClick={() => handleStart()} 
            disabled={isStartDisabled}
            className={`w-full flex items-center justify-center font-bold py-4 px-4 rounded-lg transition-colors duration-300 shadow-lg shadow-highlight/20 active:scale-95
                ${isStartDisabled 
                    ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                    : 'bg-highlight hover:bg-teal-500 text-primary'}`
            }
          >
              {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Shuffle className="mr-2 h-5 w-5"/>} 
              {state.status === AuctionStatus.NotStarted ? 'Start Auction (Auto Random)' : 'Next Random Player'}
          </button>
      );
  }

  // --- RENDER QUICK BID BUTTONS (Inline Grid) ---
  const isRoundActive = state.status === AuctionStatus.InProgress && state.currentPlayerId;
  const renderQuickBidButtons = () => {
        if (!isRoundActive || isSellingMode) return null;

        return (
            <div className="mb-4">
                <h3 className="text-xs font-bold text-text-secondary uppercase mb-2 flex items-center">
                    <Zap className="w-3 h-3 mr-1 text-yellow-400" /> Quick Bids (Next: {nextBid})
                </h3>
                <div className="grid grid-cols-2 gap-2">
                    {teams.map(team => {
                        let allowed = true;
                        let reason = '';
                        if (team.budget < nextBid) { allowed = false; reason = 'NO FUNDS'; }
                        else if (state.highestBidder?.id === team.id) { allowed = false; reason = 'LEADING'; }
                        else if (team.players.length >= (maxPlayersPerTeam || 25)) { allowed = false; reason = 'FULL'; }
                        else if (currentPlayer) {
                            if (currentPlayer.category) {
                                const catConfig = categories.find(c => c.name === currentPlayer.category);
                                if (catConfig && catConfig.maxPerTeam > 0) {
                                    const count = team.players.filter(p => p.category === currentPlayer.category).length;
                                    if (count >= catConfig.maxPerTeam) { allowed = false; reason = 'CAT LIMIT'; }
                                }
                            }
                            if (allowed) {
                                let reservedBudget = 0;
                                categories.forEach(cat => {
                                    if (cat.maxPerTeam > 0) {
                                        const playersInCat = team.players.filter(p => p.category === cat.name).length;
                                        let slotsToFill = Math.max(0, cat.maxPerTeam - playersInCat);
                                        if (currentPlayer.category === cat.name) {
                                            slotsToFill = Math.max(0, slotsToFill - 1);
                                        }
                                        reservedBudget += slotsToFill * cat.basePrice;
                                    }
                                });
                                const maxAllowedBid = team.budget - reservedBudget;
                                if (nextBid > maxAllowedBid) { allowed = false; reason = 'MAX BID'; }
                            }
                        }

                        return (
                            <button
                                key={team.id}
                                onClick={() => handleQuickBid(team.id)}
                                disabled={!allowed || isProcessing}
                                className={`
                                    flex items-center justify-between px-2 py-2 rounded border text-left transition-all relative group
                                    ${allowed 
                                        ? 'bg-white border-gray-300 hover:border-green-500 hover:shadow-md active:scale-95' 
                                        : 'bg-gray-200 border-transparent opacity-60 cursor-not-allowed'}
                                `}
                            >
                                <div className="flex items-center gap-2 min-w-0 flex-1">
                                    {team.logoUrl ? (
                                        <img src={team.logoUrl} className="w-6 h-6 rounded-full object-contain bg-gray-100 flex-shrink-0" alt="" />
                                    ) : (
                                        <div className="w-6 h-6 rounded-full bg-gray-300 flex items-center justify-center text-[10px] font-bold text-gray-600 flex-shrink-0">
                                            {team.name.charAt(0)}
                                        </div>
                                    )}
                                    <div className="flex flex-col min-w-0">
                                        <span className="text-xs font-bold text-gray-800 truncate leading-none">{team.name}</span>
                                        <span className="text-[9px] text-gray-500 font-mono leading-none mt-0.5">{team.budget}</span>
                                    </div>
                                </div>

                                <div className="flex-shrink-0 ml-1">
                                    {!allowed ? (
                                        <span className="text-[8px] font-black text-red-500 uppercase bg-red-100 px-1 rounded">{reason}</span>
                                    ) : (
                                        <span className="text-[10px] font-bold text-green-600 bg-green-50 px-1.5 py-0.5 rounded group-hover:bg-green-600 group-hover:text-white transition-colors">
                                            +{nextBid}
                                        </span>
                                    )}
                                </div>
                            </button>
                        );
                    })}
                </div>
            </div>
        );
  };

  return (
    <div className="bg-secondary p-4 rounded-lg shadow-lg h-full flex flex-col border border-gray-700 relative">

      <div className="flex justify-between items-center mb-4 border-b border-accent pb-2">
          <div className="flex flex-col gap-2 w-full">
              <div className="flex justify-between items-center w-full">
                <h2 className="text-xl font-bold text-highlight uppercase tracking-wider">Auctioneer</h2>
                <button onClick={() => navigate('/admin')} className="text-xs text-text-secondary hover:text-white flex items-center">
                    <ArrowLeft className="w-3 h-3 mr-1"/> Dashboard
                </button>
              </div>

