            if (collection === 'categories') setCategories(prev => prev.filter(c => c.id !== itemId));
            if (collection === 'sponsors') setSponsors(prev => prev.filter(s => s.id !== itemId));
            if (collection === 'roles') setRoles(prev => prev.filter(r => r.id !== itemId));
