export default AuctionManage;

import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../firebase';
import { AuctionSetup, RegistrationConfig, FormField, PlayerRole } from '../types';
import { Upload, Calendar, CheckCircle, AlertTriangle, ArrowUpCircle, FileText, Home, ArrowLeft, Loader2, CreditCard, QrCode, Check, Play, ExternalLink, Zap } from 'lucide-react';

const PlayerRegistration: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [auction, setAuction] = useState<AuctionSetup | null>(null);
    const [config, setConfig] = useState<RegistrationConfig | null>(null);
    const [roles, setRoles] = useState<PlayerRole[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState(false);
    const [submitting, setSubmitting] = useState(false);

    // Current step in the registration process
    const [step, setStep] = useState<'FORM' | 'PAYMENT'>('FORM');

    // Form Data
    const [formData, setFormData] = useState({
        fullName: '',
        playerType: '',
        gender: '',
        mobile: '',
        dob: '',
        captcha: ''
    });

    // Dynamic Form Data (Map field ID -> Value)
    const [customData, setCustomData] = useState<Record<string, any>>({});
    const [paymentRef, setPaymentRef] = useState(''); // Transaction ID from user

    // File Data
    const [profilePic, setProfilePic] = useState<string>('');
    const [paymentScreenshot, setPaymentScreenshot] = useState<string>('');

    const profileInputRef = useRef<HTMLInputElement>(null);
    const paymentInputRef = useRef<HTMLInputElement>(null);

    // Helper to compress images
    const compressImage = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (event) => {
                const img = new Image();
                img.src = event.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const MAX_WIDTH = 800;
                    const MAX_HEIGHT = 800;
                    let width = img.width;
                    let height = img.height;

                    if (width > height) {
                        if (width > MAX_WIDTH) {
                            height *= MAX_WIDTH / width;
                            width = MAX_WIDTH;
                        }
                    } else {
                        if (height > MAX_HEIGHT) {
                            width *= MAX_HEIGHT / height;
                            height = MAX_HEIGHT;
                        }
                    }
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    ctx?.drawImage(img, 0, 0, width, height);
                    resolve(canvas.toDataURL('image/jpeg', 0.7)); 
                };
                img.onerror = (err) => reject(err);
            };
            reader.onerror = (err) => reject(err);
        });
    };

    // Load Auction Config & Roles
    useEffect(() => {
        const fetchAuction = async () => {
            if (!id) return;
            try {
                const docSnap = await db.collection('auctions').doc(id).get();
                if (docSnap.exists) {
                    const data = docSnap.data() as AuctionSetup;
                    setAuction(data);
                    if (data.registrationConfig && data.registrationConfig.isEnabled) {
                        setConfig(data.registrationConfig);
                    } else {
                        setError("Registration is currently closed for this auction.");
                    }
                } else {
                    setError("Auction not found.");
                }

                const roleSnap = await db.collection('auctions').doc(id).collection('roles').get();
                setRoles(roleSnap.docs.map(d => ({ id: d.id, ...d.data() } as PlayerRole)));

            } catch (e) {
                console.error(e);
                setError("Failed to load registration form.");
            } finally {
                setLoading(false);
            }
        };
        fetchAuction();
    }, [id]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleCustomChange = (fid: string, value: any) => {
        setCustomData(prev => ({ ...prev, [fid]: value }));
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'profile' | 'payment' | 'custom', customFieldId?: string) => {
        const file = e.target.files?.[0];
        if (file) {
            try {
                if (!file.type.startsWith('image/')) {
                    alert("Please upload an image file (JPG/PNG).");
                    return;
                }
                const compressedBase64 = await compressImage(file);
                if (type === 'profile') setProfilePic(compressedBase64);
                else if (type === 'payment') setPaymentScreenshot(compressedBase64);
                else if (customFieldId) handleCustomChange(customFieldId, compressedBase64);
            } catch (err) {
                alert("Failed to process image.");
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (step === 'FORM') {
            const inputCaptcha = formData.captcha.replace(/\s+/g, '').toLowerCase();
            const expectedCaptcha = 'dej7ym'; 
            if (inputCaptcha !== expectedCaptcha) return alert("Incorrect Captcha.");

            if (!profilePic) return alert("Please upload profile picture");

            // Move to Payment Step if required
            if (config?.includePayment) {
                setStep('PAYMENT');
                window.scrollTo(0, 0);
            } else {
                finalizeSubmission();
            }
        } else {
            // PAYMENT STEP VALIDATION
            if (!paymentRef.trim()) return alert("Please enter your Transaction Reference ID.");
            finalizeSubmission();
        }
    };

    const finalizeSubmission = async () => {
        if (!id) return;
        setSubmitting(true);
        try {
            const submissionData = {
                ...formData,
                profilePic,
                paymentReferenceId: paymentRef,
                paymentScreenshot: config?.paymentMethod === 'MANUAL' ? paymentScreenshot : '',
                ...customData,
                submittedAt: Date.now(),
                status: 'PENDING'
            };

            await db.collection('auctions').doc(id).collection('registrations').add(submissionData);

            setSuccess(true);
            window.scrollTo(0,0);
            setTimeout(() => navigate('/'), 5000);
        } catch (e: any) {
            alert("Database Error: " + e.message);
        } finally {
            setSubmitting(false);
        }
    };

    const renderField = (field: FormField) => {
        const commonClasses = "w-full border border-gray-300 rounded-lg p-2.5 bg-white outline-none focus:ring-2 focus:ring-green-500 transition-shadow text-gray-900";

        switch (field.type) {
            case 'select':
                return (
                    <select 
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={commonClasses}
                    >
                        <option value="">Select an option</option>
                        {field.options?.map((opt, i) => (
                            <option key={i} value={opt}>{opt}</option>
                        ))}
                    </select>
                );
            case 'file':
                return (
                    <div className="border-2 border-dashed border-gray-300 rounded-xl p-4 text-center cursor-pointer hover:bg-gray-50 flex items-center justify-center text-sm text-gray-500 relative">
                        <input 
                            type="file" 
                            accept="image/*" 
                            required={field.required && !customData[field.id]} 
                            className="absolute inset-0 opacity-0 cursor-pointer" 
                            onChange={(e) => handleFileUpload(e, 'custom', field.id)}
                        />
                         {customData[field.id] ? (
                            <span className="text-green-600 font-bold flex items-center truncate max-w-xs">
                                <CheckCircle className="w-4 h-4 mr-2"/> Image Selected
                            </span>
                         ) : (
                            <span className="flex items-center gap-2"><FileText className="w-4 h-4"/> Click to Upload Image</span>
                         )}
                    </div>
                );
            case 'textarea':
                return (
                    <textarea 
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={`${commonClasses} min-h-[100px]`}
                        placeholder={field.placeholder}
                    />
                );
            default:
                return (
                    <input 
                        type={field.type}
                        placeholder={field.placeholder}
                        required={field.required}
                        value={customData[field.id] || ''}
                        onChange={(e) => handleCustomChange(field.id, e.target.value)}
                        className={commonClasses}
                    />
                );
        }
    };

    if (loading) return (
        <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
            <Loader2 className="w-10 h-10 animate-spin text-green-600 mb-4" />
            <p className="text-gray-500 font-bold uppercase tracking-widest text-xs">Syncing Registration Protocol...</p>
        </div>
    );

    if (error) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
                <div className="bg-white p-8 rounded-2xl shadow-xl text-center max-w-md border border-red-100">
                    <AlertTriangle className="w-16 h-16 text-red-500 mx-auto mb-4" />
                    <h2 className="text-xl font-bold text-gray-800 mb-2">Notice</h2>
                    <p className="text-gray-600 mb-6">{error}</p>
                    <button onClick={() => navigate('/')} className="bg-gray-800 text-white px-8 py-2 rounded-lg font-bold">Back to Home</button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-100 font-sans py-10 px-4 relative">
            <div className="max-w-3xl mx-auto mb-6">
                <button onClick={() => navigate('/')} className="flex items-center text-gray-500 hover:text-gray-900 transition-colors font-bold text-sm uppercase tracking-widest">
                    <ArrowLeft className="w-4 h-4 mr-2" /> Back to Terminal
                </button>
            </div>

            {success && (
                <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-fade-in">
                    <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full p-10 text-center transform transition-all scale-100 border-t-8 border-green-500">
                        <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <CheckCircle className="w-12 h-12 text-green-600" />
                        </div>
                        <h2 className="text-3xl font-black text-gray-900 mb-2 uppercase tracking-tighter">Verified & Registered</h2>
                        <p className="text-gray-500 mb-8 font-medium">
                            Your application is now being processed. Welcome to the pool, <span className="text-green-600 font-bold">{formData.fullName}</span>.
                        </p>
                        <button 
                            onClick={() => navigate('/')}
                            className="w-full bg-gray-900 hover:bg-black text-white font-black py-4 rounded-xl shadow-xl transition-all flex items-center justify-center gap-3"
                        >
                            <Home className="w-5 h-5" /> RETURN TO HOME
                        </button>
                        <p className="text-[10px] text-gray-400 mt-6 font-bold uppercase tracking-widest animate-pulse">Auto-redirecting shortly...</p>
                    </div>
                </div>
            )}

            <div className={`max-w-3xl mx-auto bg-white shadow-2xl rounded-[2.5rem] overflow-hidden border border-gray-200 ${success ? 'blur-sm pointer-events-none' : ''}`}>

                <div className="p-8 md:p-12 pb-6">
                    {config?.bannerUrl && (
                        <div className="flex justify-center mb-8">
                            <img src={config.bannerUrl} alt="Logo" className="h-28 object-contain drop-shadow-xl" />
                        </div>
                    )}
                    <div className="text-center">
                        <h1 className="text-3xl font-black text-gray-900 mb-2 tracking-tight uppercase">{auction?.title}</h1>
                        <p className="text-gray-400 font-bold uppercase tracking-[0.3em] text-[10px]">Step {step === 'FORM' ? '1' : '2'}: {step === 'FORM' ? 'Details Matrix' : 'Payment Protocol'}</p>
                    </div>
                </div>

                <form onSubmit={handleSubmit} className="px-8 md:px-12 pb-12">
                    {step === 'FORM' ? (
                        <div className="space-y-10">
                            {/* SECTION 1: IDENTITY */}
                            <div className="space-y-6">
                                <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] border-b border-gray-100 pb-2">01. Identity Matrix</h3>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="col-span-1 md:col-span-2">
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Full Legal Name</label>
                                        <input required name="fullName" type="text" onChange={handleInputChange} value={formData.fullName} className="w-full border border-gray-300 rounded-xl p-3 focus:ring-4 ring-green-500/10 outline-none text-gray-900 font-bold" placeholder="E.G. JOHN SMITH" />
                                    </div>

                                    <div>
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Visual Identity (Profile Pic)</label>
                                        <div 
                                            onClick={() => profileInputRef.current?.click()}
                                            className="border-2 border-dashed border-gray-300 rounded-2xl p-6 text-center cursor-pointer hover:bg-gray-50 transition-all flex flex-col items-center justify-center gap-2"
                                        >
                                            <input ref={profileInputRef} type="file" accept="image/*" className="hidden" onChange={e => handleFileUpload(e, 'profile')} />
                                            {profilePic ? (
                                                <div className="relative">
                                                    <img src={profilePic} className="w-16 h-16 rounded-full object-cover border-2 border-green-500" />
                                                    <div className="absolute -top-1 -right-1 bg-green-500 text-white rounded-full p-1 shadow-lg"><Check className="w-3 h-3"/></div>
                                                </div>
                                            ) : (
                                                <Upload className="w-8 h-8 text-gray-300" />
                                            )}
                                            <span className="text-[10px] font-bold text-gray-400 uppercase">Click to Select</span>
                                        </div>
                                    </div>

                                    <div className="space-y-6">
                                        <div>
                                            <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Combat Role (Player Type)</label>
                                            <select required name="playerType" onChange={handleInputChange} value={formData.playerType} className="w-full border border-gray-300 rounded-xl p-3 bg-white outline-none text-gray-900 font-bold uppercase">
                                                <option value="">SELECT ROLE</option>
                                                {roles.map(role => <option key={role.id} value={role.name}>{role.name.toUpperCase()}</option>)}
                                            </select>
                                        </div>
                                        <div>
                                            <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Gender Identification</label>
                                            <select required name="gender" onChange={handleInputChange} value={formData.gender} className="w-full border border-gray-300 rounded-xl p-3 bg-white outline-none text-gray-900 font-bold uppercase">
                                                <option value="">SELECT GENDER</option>
                                                <option value="Male">MALE</option>
                                                <option value="Female">FEMALE</option>
                                            </select>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* SECTION 2: CONNECTIVITY */}
                            <div className="space-y-6">
                                <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] border-b border-gray-100 pb-2">02. Comms & Chrono</h3>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div>
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Mobile (WhatsApp Enabled)</label>
                                        <input required name="mobile" type="tel" onChange={handleInputChange} value={formData.mobile} className="w-full border border-gray-300 rounded-xl p-3 outline-none text-gray-900 font-bold font-mono" placeholder="+91 XXXX XXX XXX" />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Date of Birth</label>
                                        <div className="relative">
                                            <input required name="dob" type="date" onChange={handleInputChange} value={formData.dob} className="w-full border border-gray-300 rounded-xl p-3 outline-none text-gray-900 font-bold pr-10" />
                                            <Calendar className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* SECTION 3: PROTOCOL DATA */}
                            {config?.customFields && config.customFields.length > 0 && (
                                <div className="space-y-6">
                                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] border-b border-gray-100 pb-2">03. Custom Protocol Data</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-6">
                                        {config.customFields.map((field) => (
                                            <div key={field.id} className={field.type === 'textarea' ? 'col-span-full' : ''}>
                                                <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">
                                                    {field.label} {field.required && <span className="text-red-500">*</span>}
                                                </label>
                                                {renderField(field)}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* SECTION 4: VERIFICATION */}
                            <div className="space-y-6">
                                <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] border-b border-gray-100 pb-2">04. Anti-Bot Verification</h3>
                                <div className="flex flex-col md:flex-row gap-6 items-end">
                                    <div className="flex-1 w-full">
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Sequence Entry</label>
                                        <input required type="text" name="captcha" onChange={handleInputChange} className="w-full border border-gray-300 rounded-xl p-3 outline-none text-gray-900 font-bold uppercase tracking-[0.5em]" placeholder="XXXXXX" />
                                    </div>
                                    <div className="bg-zinc-100 px-6 py-3 rounded-2xl border-2 border-zinc-200 select-none shadow-inner">
                                        <span className="font-mono text-2xl tracking-[0.4em] text-zinc-400 font-black italic line-through decoration-red-500/30">dej7ym</span>
                                    </div>
                                </div>
                            </div>

                            <button 
                                type="submit" 
                                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-6 rounded-2xl shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-[0.98] uppercase tracking-[0.2em]"
                            >
                                {config?.includePayment ? 'PROCEED TO PAYMENT' : 'FINALIZE REGISTRATION'} <Play className="w-4 h-4 fill-current"/>
                            </button>
                        </div>
                    ) : (
                        // PAYMENT STEP
                        <div className="space-y-8 animate-fade-in">
                            <div className="bg-zinc-50 border border-zinc-200 p-8 rounded-[2.5rem] relative overflow-hidden">
                                <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 blur-3xl rounded-full"></div>
                                <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em] mb-6 flex items-center gap-2">
                                    <CreditCard className="w-4 h-4" /> Secure Transfer Matrix
                                </h3>

                                <div className="text-center space-y-4">
                                    <p className="text-[10px] font-bold text-gray-400 uppercase">Registration Fee Required</p>
                                    <p className="text-6xl font-black text-gray-900 tracking-tighter">₹{config?.fee}</p>

                                    {config?.paymentMethod === 'RAZORPAY_PAGE' ? (
                                        <div className="pt-6 space-y-6">
                                            <a 
                                                href={config.paymentPageUrl} 
                                                target="_blank" 
                                                rel="noopener noreferrer"
                                                className="inline-flex items-center gap-3 bg-green-600 hover:bg-green-700 text-white px-10 py-5 rounded-2xl font-black shadow-xl transition-all hover:scale-105 active:scale-95 group"
                                            >
                                                PAY ON RAZORPAY <ExternalLink className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                                            </a>
                                            <p className="text-[10px] text-gray-500 font-medium max-w-sm mx-auto leading-relaxed">
                                                Click the button above to pay on the official Razorpay terminal. After successful payment, copy the <b>Transaction ID</b> or <b>Payment ID</b> and paste it below.
                                            </p>
                                        </div>
                                    ) : (
                                        <div className="pt-4 space-y-6">
                                            <div className="bg-white p-6 inline-block rounded-[2rem] shadow-xl border border-zinc-200">
                                                <img src={config?.qrCodeUrl} className="w-48 h-48 object-contain" alt="Scan to Pay" />
                                            </div>
                                            <div>
                                                <h4 className="text-sm font-black text-blue-900">{config?.upiName}</h4>
                                                <p className="text-xl font-black text-blue-600 font-mono tracking-tighter">{config?.upiId}</p>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="bg-white p-8 rounded-[2.5rem] border-4 border-blue-50 shadow-inner">
                                <label className="block text-[10px] font-black text-blue-600 uppercase tracking-widest mb-4 flex items-center gap-2">
                                    <Zap className="w-4 h-4 text-yellow-500" /> Payment Confirmation Code
                                </label>
                                <input 
                                    required 
                                    type="text" 
                                    placeholder="PASTE TRANSACTION / UTR ID HERE" 
                                    className="w-full bg-blue-50/50 border-2 border-blue-100 rounded-2xl p-5 text-center text-lg font-black tracking-widest text-blue-900 focus:border-blue-400 outline-none transition-all placeholder:text-blue-200 uppercase"
                                    value={paymentRef}
                                    onChange={e => setPaymentRef(e.target.value)}
                                />
                                <p className="text-[9px] text-gray-400 mt-4 text-center font-bold uppercase tracking-widest">
                                    Final submission requires a valid reference ID for manual audit
                                </p>
                            </div>

                            {config?.paymentMethod === 'MANUAL' && (
                                <div className="bg-blue-50/50 p-6 rounded-3xl border border-blue-100">
                                    <label className="block text-[10px] font-black text-blue-500 uppercase tracking-widest mb-3">Transmission Receipt (ScreenShot)</label>
                                    <div 
                                        onClick={() => paymentInputRef.current?.click()}
                                        className="border-2 border-dashed border-blue-200 rounded-2xl p-6 text-center cursor-pointer hover:bg-white transition-all flex flex-col items-center justify-center gap-2"
                                    >
                                        <input ref={paymentInputRef} type="file" accept="image/*" className="hidden" onChange={e => handleFileUpload(e, 'payment')} />
                                        {paymentScreenshot ? (
                                            <div className="flex items-center gap-2 text-green-600 font-black text-xs uppercase">
                                                <CheckCircle className="w-5 h-5"/> Image Attached
                                            </div>
                                        ) : (
                                            <div className="flex flex-col items-center gap-2">
                                                <Upload className="w-6 h-6 text-blue-300" />
                                                <span className="text-[10px] font-bold text-blue-400 uppercase">Select Screenshot</span>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}

                            <div className="flex flex-col md:flex-row gap-4 pt-4">
                                <button 
                                    type="button" 
                                    onClick={() => setStep('FORM')}
                                    className="flex-1 border-2 border-gray-200 text-gray-400 font-black py-5 rounded-2xl uppercase tracking-widest hover:bg-gray-50 active:scale-95 transition-all text-xs"
                                >
                                    Modify Form
                                </button>
                                <button 
                                    type="submit" 
                                    disabled={submitting || !paymentRef.trim()}
                                    className={`flex-[2] bg-green-600 hover:bg-green-700 text-white font-black py-5 rounded-2xl shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-[0.98] uppercase tracking-[0.2em] disabled:opacity-40 disabled:cursor-not-allowed disabled:grayscale`}
                                >
                                    {submitting ? (
                                        <><Loader2 className="w-6 h-6 animate-spin"/> TRANSMITTING...</>
                                    ) : (
                                        <><Play className="w-5 h-5 fill-current"/> FINALIZE ENROLLMENT</>
                                    )}
                                </button>
                            </div>
                        </div>
                    )}
                </form>

                <div className="p-10 bg-zinc-900 border-t border-white/5 text-[10px] text-zinc-500 leading-relaxed text-center">
                    <div className="w-12 h-12 bg-green-600/20 text-green-500 font-black flex items-center justify-center rounded-xl mx-auto mb-6 text-xs border border-green-500/20">SM</div>
                    <p className="font-black uppercase tracking-[0.3em] mb-4 text-zinc-300">SM SPORTS CORE PROTOCOL</p>
                    <p className="max-w-md mx-auto mb-8 opacity-60">
                        Registration data is archived for auditor review. Ensure all reference IDs match your transaction details to prevent application purging.
                    </p>
                    <p className="font-black text-zinc-600 uppercase tracking-widest">© 2025 SM SPORTS. ALL SYSTEMS NOMINAL.</p>
                </div>
            </div>

            <button onClick={() => window.scrollTo({top: 0, behavior: 'smooth'})} className="fixed bottom-8 right-8 bg-green-600 hover:bg-green-700 text-white p-4 rounded-2xl shadow-2xl transition-all active:scale-90 z-10 hover:shadow-green-500/20">
                <ArrowUpCircle className="w-6 h-6" />
            </button>
        </div>
    );
};

