import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../firebase';
import { AuctionSetup, RegistrationConfig, FormField, PlayerRole } from '../types';
import { Upload, Calendar, CheckCircle, AlertTriangle, ArrowUpCircle, FileText, Home, ArrowLeft, Loader2, CreditCard, Play, Zap, ExternalLink } from 'lucide-react';

const PlayerRegistration: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [auction, setAuction] = useState<AuctionSetup | null>(null);
    const [config, setConfig] = useState<RegistrationConfig | null>(null);
    const [roles, setRoles] = useState<PlayerRole[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState(false);
    const [submitting, setSubmitting] = useState(false);

    // Form Data
    const [formData, setFormData] = useState({
        fullName: '',
        playerType: '',
        gender: '',
        mobile: '',
        dob: '',
        captcha: ''
    });

    // Dynamic Form Data
    const [customData, setCustomData] = useState<Record<string, any>>({});
    const [profilePic, setProfilePic] = useState<string>('');
    const profileInputRef = useRef<HTMLInputElement>(null);

    // Helper to compress images
    const compressImage = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (event) => {
                const img = new Image();
                img.src = event.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const MAX_WIDTH = 600;
                    const MAX_HEIGHT = 600;
                    let width = img.width;
                    let height = img.height;
                    if (width > height) {
                        if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; }
                    } else {
                        if (height > MAX_HEIGHT) { width *= MAX_HEIGHT / height; height = MAX_HEIGHT; }
                    }
                    canvas.width = width; canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    ctx?.drawImage(img, 0, 0, width, height);
                    resolve(canvas.toDataURL('image/jpeg', 0.6)); 
                };
                img.onerror = (err) => reject(err);
            };
            reader.onerror = (err) => reject(err);
        });
    };

    useEffect(() => {
        const fetchAuction = async () => {
            if (!id) return;
            try {
                const docSnap = await db.collection('auctions').doc(id).get();
                if (docSnap.exists) {
                    const data = docSnap.data() as AuctionSetup;
                    setAuction(data);
                    if (data.registrationConfig && data.registrationConfig.isEnabled) {
                        setConfig(data.registrationConfig);
                    } else {
                        setError("Registration is currently closed for this auction.");
                    }
                } else {
                    setError("Auction not found.");
                }
                const roleSnap = await db.collection('auctions').doc(id).collection('roles').get();
                setRoles(roleSnap.docs.map(d => ({ id: d.id, ...d.data() } as PlayerRole)));
            } catch (e) {
                console.error(e);
                setError("Failed to load registration form.");
            } finally {
                setLoading(false);
            }
        };
        fetchAuction();
    }, [id]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleCustomChange = (fid: string, value: any) => {
        setCustomData(prev => ({ ...prev, [fid]: value }));
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            try {
                if (!file.type.startsWith('image/')) {
                    alert("Please upload an image file (JPG/PNG).");
                    return;
                }
                const compressedBase64 = await compressImage(file);
                setProfilePic(compressedBase64);
            } catch (err) {
                alert("Failed to process image.");
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!id || !config) return;

        const inputCaptcha = formData.captcha.replace(/\s+/g, '').toLowerCase();
        if (inputCaptcha !== 'dej7ym') return alert("Incorrect Captcha.");
        if (!profilePic) return alert("Please upload profile picture");

        setSubmitting(true);
        try {
            // 1. Save data as PENDING
            const submissionData = {
                ...formData,
                profilePic,
                ...customData,
                paymentStatus: 'pending',
                submittedAt: Date.now(),
            };

            const docRef = await db.collection('auctions').doc(id).collection('registrations').add(submissionData);

            // 2. Redirect to Razorpay Page with reference_id
            if (config.includePayment && config.paymentMethod === 'RAZORPAY_PAGE' && config.razorpayPageUrl) {
                const connector = config.razorpayPageUrl.includes('?') ? '&' : '?';
                const redirectUrl = `${config.razorpayPageUrl}${connector}reference_id=${docRef.id}`;

                // Show a brief redirect message
                setSuccess(true);
                setTimeout(() => {
                    window.location.href = redirectUrl;
                }, 1500);
            } else {
                // Manual or Free
                setSuccess(true);
                setTimeout(() => navigate('/'), 3000);
            }
        } catch (e: any) {
            alert("Registration Error: " + e.message);
            setSubmitting(false);
        }
    };

    const renderField = (field: FormField) => {
        const commonClasses = "w-full border border-gray-300 rounded-lg p-2.5 bg-white outline-none focus:ring-2 focus:ring-blue-500 transition-shadow text-gray-900";
        if (field.type === 'select') {
            return (
                <select required={field.required} value={customData[field.id] || ''} onChange={(e) => handleCustomChange(field.id, e.target.value)} className={commonClasses}>
                    <option value="">Select an option</option>
                    {field.options?.map((opt, i) => (<option key={i} value={opt}>{opt}</option>))}
                </select>
            );
        }
        return <input type={field.type} placeholder={field.placeholder} required={field.required} value={customData[field.id] || ''} onChange={(e) => handleCustomChange(field.id, e.target.value)} className={commonClasses} />;
    };

    if (loading) return (
        <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
            <Loader2 className="w-10 h-10 animate-spin text-blue-600 mb-4" />
            <p className="text-gray-500 font-bold uppercase tracking-widest text-xs">Accessing Portal...</p>
        </div>
    );

    if (error) return (
        <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
            <div className="bg-white p-8 rounded-2xl shadow-xl text-center max-w-md border border-red-100">
                <AlertTriangle className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-xl font-bold text-gray-800 mb-2">Access Denied</h2>
                <p className="text-gray-600 mb-6">{error}</p>
                <button onClick={() => navigate('/')} className="bg-gray-800 text-white px-8 py-2 rounded-lg font-bold">Back to Home</button>
            </div>
        </div>
    );

    return (
        <div className="min-h-screen bg-gray-100 font-sans py-10 px-4 relative">
            <div className="max-w-3xl mx-auto mb-6">
                <button onClick={() => navigate('/')} className="flex items-center text-gray-500 hover:text-gray-900 transition-colors font-bold text-sm uppercase tracking-widest">
                    <ArrowLeft className="w-4 h-4 mr-2" /> Cancel
                </button>
            </div>

            {success && (
                <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full p-10 text-center animate-fade-in border-t-8 border-blue-500">
                        <div className="w-24 h-24 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <CheckCircle className="w-12 h-12 text-blue-600" />
                        </div>
                        <h2 className="text-2xl font-black text-gray-900 mb-2 uppercase tracking-tighter">Identity Cached</h2>
                        <p className="text-gray-500 mb-8 font-medium">
                            Redirecting to secure payment gateway...
                        </p>
                        <Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto" />
                    </div>
                </div>
            )}

            <div className={`max-w-3xl mx-auto bg-white shadow-2xl rounded-[2.5rem] overflow-hidden border border-gray-200 ${success ? 'blur-sm pointer-events-none' : ''}`}>
                <div className="p-8 md:p-12 pb-6">
                    {config?.bannerUrl && (
                        <div className="flex justify-center mb-8">
                            <img src={config.bannerUrl} alt="Logo" className="h-28 object-contain drop-shadow-xl" />
                        </div>
                    )}
                    <div className="text-center">
                        <h1 className="text-3xl font-black text-gray-900 mb-2 tracking-tight uppercase">{auction?.title}</h1>
                        <p className="text-gray-400 font-bold uppercase tracking-[0.3em] text-[10px]">Official Registration Terminal</p>
                    </div>
                </div>

                <form onSubmit={handleSubmit} className="px-8 md:px-12 pb-12">
                    <div className="space-y-10">
                        {/* IDENTITY */}
                        <div className="space-y-6">
                            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] border-b border-gray-100 pb-2">01. identity matrix</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="col-span-1 md:col-span-2">
                                    <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Full Legal Name</label>
                                    <input required name="fullName" type="text" onChange={handleInputChange} className="w-full border border-gray-300 rounded-xl p-3 focus:ring-4 ring-blue-500/10 outline-none text-gray-900 font-bold" placeholder="E.G. JOHN DOE" />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Profile Image</label>
                                    <div onClick={() => profileInputRef.current?.click()} className="border-2 border-dashed border-gray-300 rounded-2xl p-6 text-center cursor-pointer hover:bg-gray-50 transition-all flex flex-col items-center justify-center gap-2">
                                        <input ref={profileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
                                        {profilePic ? (
                                            <img src={profilePic} className="w-16 h-16 rounded-full object-cover border-2 border-blue-500" alt="Profile" />
                                        ) : (
                                            <Upload className="w-8 h-8 text-gray-300" />
                                        )}
                                        <span className="text-[9px] font-bold text-gray-400 uppercase">Upload Identity</span>
                                    </div>
                                </div>
                                <div className="space-y-6">
                                    <div>
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Player Type</label>
                                        <select required name="playerType" onChange={handleInputChange} className="w-full border border-gray-300 rounded-xl p-3 bg-white outline-none text-gray-900 font-bold">
                                            <option value="">SELECT ROLE</option>
                                            {roles.map(role => <option key={role.id} value={role.name}>{role.name.toUpperCase()}</option>)}
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Gender</label>
                                        <select required name="gender" onChange={handleInputChange} className="w-full border border-gray-300 rounded-xl p-3 bg-white outline-none text-gray-900 font-bold">
                                            <option value="">SELECT GENDER</option>
                                            <option value="Male">MALE</option>
                                            <option value="Female">FEMALE</option>
                                        </select>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* CONTACT */}
                        <div className="space-y-6">
                            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] border-b border-gray-100 pb-2">02. comms hub</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Mobile (WhatsApp)</label>
                                    <input required name="mobile" type="tel" onChange={handleInputChange} className="w-full border border-gray-300 rounded-xl p-3 outline-none text-gray-900 font-bold font-mono" placeholder="91XXXXXXXXXX" />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">D.O.B</label>
                                    <input required name="dob" type="date" onChange={handleInputChange} className="w-full border border-gray-300 rounded-xl p-3 outline-none text-gray-900 font-bold" />
                                </div>
                            </div>
                        </div>

                        {/* CUSTOM DATA */}
                        {config?.customFields && config.customFields.length > 0 && (
                            <div className="space-y-6">
                                <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] border-b border-gray-100 pb-2">03. technical data</h3>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    {config.customFields.map((field) => (
                                        <div key={field.id} className={field.type === 'textarea' ? 'col-span-full' : ''}>
                                            <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">
                                                {field.label} {field.required && <span className="text-red-500">*</span>}
                                            </label>
                                            {renderField(field)}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* BOT PROTECTION */}
                        <div className="space-y-6">
                            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] border-b border-gray-100 pb-2">04. verification</h3>
                            <div className="flex flex-col md:flex-row gap-6 items-end">
                                <div className="flex-1 w-full">
                                    <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Entry Code</label>
                                    <input required type="text" name="captcha" onChange={handleInputChange} className="w-full border border-gray-300 rounded-xl p-3 outline-none text-gray-900 font-bold uppercase tracking-[0.5em]" placeholder="XXXXXX" />
