/**
 * GUIDE: RAZORPAY WEBHOOK FOR FIREBASE
 * 
 * 1. Create a folder named 'functions' in your project root.
 * 2. Run 'npm install razorpay firebase-admin' inside it.
 * 3. Copy this code into index.js.
 * 4. Deploy using 'firebase deploy --only functions'.
 * 5. Set your Webhook Secret in Firebase Config.
 */

const functions = require('firebase-functions');
const admin = require('firebase-admin');
const crypto = require('crypto');

admin.initializeApp();
const db = admin.firestore();

exports.razorpayWebhook = functions.https.onRequest(async (req, res) => {
    // 1. Verify Signature
    const secret = "YOUR_RAZORPAY_WEBHOOK_SECRET"; // Set this to the secret you put in Razorpay Dashboard
    const signature = req.headers['x-razorpay-signature'];

    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(JSON.stringify(req.body));
    const generatedSignature = hmac.digest('hex');

    if (generatedSignature !== signature) {
        console.error("Invalid Webhook Signature");
        return res.status(400).send("Invalid signature");
    }

    const event = req.body.event;
    const payload = req.body.payload;

    // 2. Handle Payment Success
    if (event === 'payment.captured') {
        const payment = payload.payment.entity;

        // Extract reference_id passed from frontend redirect
        // Razorpay Payment Pages pass query params into the 'notes' or 'description' usually
        // But if you used the query param redirect logic, reference_id is often in the 'notes'
        const referenceId = payment.notes.reference_id || payment.description.split('ref:')[1];
        const paymentId = payment.id;

        if (referenceId) {
            try {
                // Find document in sub-collection
                // Since auctions are top-level, we might need a collectionGroup query 
                // OR store the auctionId in the notes as well to target the doc directly.

                const registrationsRef = db.collectionGroup('registrations');
                const query = registrationsRef.where(admin.firestore.FieldPath.documentId(), '==', referenceId).limit(1);
                const snapshot = await query.get();

                if (!snapshot.empty) {
                    const doc = snapshot.docs[0];
                    await doc.ref.update({
                        paymentStatus: 'paid',
                        razorpayPaymentId: paymentId,
                        paidAt: admin.firestore.FieldValue.serverTimestamp()
                    });
                    console.log(`Successfully updated registration ${referenceId} to PAID`);
                } else {
                    console.error(`Registration document ${referenceId} not found`);
                }
            } catch (err) {
                console.error("Error updating Firestore:", err);
            }
        }
    }

    res.status(200).send("Webhook received");
});

