const functions = require('firebase-functions');
const admin = require('firebase-admin');
const crypto = require('crypto');

admin.initializeApp();
const db = admin.firestore();

/**
 * CENTRAL WEBHOOK HANDLER
 * 1. Receives payment.captured from any organizer's Razorpay account.
 * 2. Extracts "reference_id" in pattern: AUCTIONID_REGISTRATIONID.
 * 3. Fetches the specific Auction to find the correct Webhook Secret.
 * 4. Verifies signature using that user's specific secret.
 * 5. Updates the specific registration document.
 */
exports.razorpayWebhook = functions.https.onRequest(async (req, res) => {
    try {
        const payload = req.body;
        const signature = req.headers['x-razorpay-signature'];

        if (!signature) {
            return res.status(400).send("Missing signature");
        }

        const event = payload.event;
        if (event !== 'payment.captured') {
            return res.status(200).send("Ignored event");
        }

        const payment = payload.payload.payment.entity;

        // Extract reference_id (Format: auctionId_registrationId)
        // Check both 'notes' and 'description' as Razorpay Payment Pages sometimes map params differently
        const rawRef = payment.notes.reference_id || payment.description.split('ref:')[1];

        if (!rawRef || !rawRef.includes('_')) {
            console.error("Invalid reference format", rawRef);
            return res.status(400).send("Invalid reference format");
        }

        const [auctionId, regId] = rawRef.split('_');

        // 1. Fetch Auction Config to get the User's Webhook Secret
        const auctionDoc = await db.collection('auctions').doc(auctionId).get();
        if (!auctionDoc.exists) {
            console.error("Auction not found", auctionId);
            return res.status(404).send("Auction configuration missing");
        }

        const config = auctionDoc.data().registrationConfig;
        const secret = config ? config.webhookSecret : null;

        if (!secret) {
            console.error("Webhook secret missing for auction", auctionId);
            return res.status(500).send("Verification secret not configured by organizer");
        }

        // 2. Multi-Tenant Signature Verification
        const hmac = crypto.createHmac('sha256', secret);
        hmac.update(JSON.stringify(req.body));
        const generatedSignature = hmac.digest('hex');

        if (generatedSignature !== signature) {
            console.error("Signature mismatch for auction", auctionId);
            return res.status(403).send("Signature verification failed");
        }

        // 3. Update Registration as PAID
        const regRef = db.collection('auctions').doc(auctionId).collection('registrations').doc(regId);
        await regRef.update({
            paymentStatus: 'paid',
            razorpayPaymentId: payment.id,
            paidAt: admin.firestore.FieldValue.serverTimestamp()
        });

        console.log(`Verified payment ${payment.id} for Auction ${auctionId} / Reg ${regId}`);
        return res.status(200).send("Webhook Processed Successfully");

    } catch (err) {
        console.error("Webhook Error:", err);
        return res.status(500).send("Internal Server Error");
    }
});

