                                  <button 
                                    key={l}
                                    onClick={() => updateTheme('OBS', l)}
                                    className={`flex-1 px-1 py-0.5 rounded text-[7px] font-black transition-all ${state.obsLayout === l ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
                                  >
                                      {l.slice(0, 4)}
                                  </button>
                              ))}
                          </div>
                      </div>
                  </div>

                  <div className="w-px h-8 bg-gray-600 mx-1"></div>

                  <div className="flex flex-col gap-1 items-end">
                      <span className="text-[9px] text-gray-400 font-bold uppercase">Sponsors</span>
                      <div className="flex items-center gap-1">
                          <button 
                              onClick={() => updateSponsorVisibility('PROJECTOR')}
                              className={`p-1 rounded flex items-center gap-1 text-[9px] font-bold border transition-colors ${state.sponsorConfig?.showOnProjector ? 'bg-blue-600 border-blue-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}
                              title="Toggle on Projector"
                          >
                              <Monitor className="w-3 h-3"/> Proj
                          </button>
                          <button 
                              onClick={() => updateSponsorVisibility('OBS')}
                              className={`p-1 rounded flex items-center gap-1 text-[9px] font-bold border transition-colors ${state.sponsorConfig?.showOnOBS ? 'bg-purple-600 border-purple-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}
                              title="Toggle on OBS"
                          >
                              <Cast className="w-3 h-3"/> OBS
                          </button>
                          <div className="relative group w-10">
                              <input 
                                  type="number" 
                                  className="w-full bg-gray-800 text-white text-[9px] p-1 rounded border border-gray-600 text-center outline-none" 
                                  value={sponsorLoop}
                                  onChange={handleSponsorLoopChange}
                                  onBlur={saveSponsorLoop}
                                  title="Loop Interval (Sec)"
                              />
                              <Clock className="w-2 h-2 absolute top-0.5 right-0.5 text-gray-500 pointer-events-none"/>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      </div>

      {/* SELECTION MODE TOGGLE (Inline Segments) */}
      <div className="bg-primary/40 rounded-lg p-2 mb-4 flex justify-between items-center border border-gray-700">
          <span className="text-xs font-bold text-text-secondary uppercase ml-1">Selection Mode</span>
          <div className="flex bg-gray-800 rounded p-1">
              <button 
                onClick={playerSelectionMode !== 'MANUAL' ? toggleSelectionMode : undefined}
                className={`px-3 py-1 rounded text-xs font-bold transition-all ${playerSelectionMode === 'MANUAL' ? 'bg-highlight text-primary shadow' : 'text-gray-400 hover:text-white'}`}
              >
                  Manual
              </button>
              <button 
                onClick={playerSelectionMode !== 'AUTO' ? toggleSelectionMode : undefined}
                className={`px-3 py-1 rounded text-xs font-bold transition-all ${playerSelectionMode === 'AUTO' ? 'bg-highlight text-primary shadow' : 'text-gray-400 hover:text-white'}`}
              >
                  Auto
              </button>
          </div>
      </div>

      <div className="mb-6 space-y-3">
         {/* UNDO BANNER */}
         {lastAction && (
             <div className="bg-amber-100 border-l-4 border-amber-500 text-amber-700 p-3 rounded shadow-md flex justify-between items-center animate-fade-in mb-4">
                 <div className="flex items-center text-xs">
                     <AlertOctagon className="w-4 h-4 mr-2" />
                     <span>Just marked <b>{lastAction.name}</b> as <b>{lastAction.type}</b></span>
                 </div>
                 <div className="flex gap-2">
                     <button 
                        onClick={handleUndoLastAction}
                        disabled={isProcessing}
                        className="bg-amber-600 hover:bg-amber-700 text-white text-xs font-bold px-3 py-1.5 rounded flex items-center transition-colors"
                     >
                         <Undo2 className="w-3 h-3 mr-1"/> Undo
                     </button>
                     <button onClick={() => setLastAction(null)} className="text-amber-500 hover:text-amber-800"><X className="w-4 h-4"/></button>
                 </div>
             </div>
         )}

         {getControlButtons()}

         {renderQuickBidButtons()}

         {!isSellingMode && (
             <div className="grid grid-cols-2 gap-2 mt-4 pt-4 border-t border-accent/30">
                 <button 
                    onClick={handleResetPlayer} 
                    disabled={isProcessing || !state.currentPlayerId}
                    className="flex flex-col items-center justify-center bg-yellow-600 hover:bg-yellow-700 text-xs text-white py-2 rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                    title="Clears bids for current player only"
                 >
                    <RotateCcw className={`mb-1 h-4 w-4 ${isProcessing ? 'animate-spin' : ''}`}/>
                    Reset Current
                 </button>
                 <button 
                    onClick={handleResetFull} 
                    disabled={isProcessing}
                    className="flex flex-col items-center justify-center bg-red-900/80 hover:bg-red-900 text-xs text-red-200 border border-red-800 py-2 rounded transition-colors disabled:opacity-50"
                    title="Resets auction status to Not Started"
                 >
                    <AlertOctagon className={`mb-1 h-4 w-4 ${isProcessing ? 'animate-spin' : ''}`}/>
                    Reset Full
                 </button>
             </div>
         )}
      </div>

      <h3 className="text-sm font-bold mb-3 text-text-secondary uppercase">Teams Overview</h3>
      <div className="flex-grow overflow-y-auto space-y-3 pr-1 custom-scrollbar">
        {teams.map((team: Team) => (
          <TeamStatusCard key={team.id} team={team} />
        ))}
      </div>
    </div>
  );
};

export default LiveAdminPanel;

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuction } from '../hooks/useAuction';
import { Plus, Search, Menu, AlertCircle, RefreshCw, Database, Trash2, Cast, Monitor, Activity, UserPlus, Link as LinkIcon, ShieldCheck, CreditCard, Scale, FileText, ChevronRight, CheckCircle, Info, Zap, Crown, Users, Gavel, Sparkles } from 'lucide-react';
import { db } from '../firebase';
import { AuctionSetup, UserPlan, UserRole } from '../types';

const AdminDashboard: React.FC = () => {
  const { userProfile, logout } = useAuction();
  const navigate = useNavigate();
  const [auctions, setAuctions] = useState<AuctionSetup[]>([]);
  const [dbPlans, setDbPlans] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'AUCTIONS' | 'PLANS' | 'LEGAL'>('AUCTIONS');
  const [isRazorpayLoaded, setIsRazorpayLoaded] = useState(false);
  const [selectedAuctionForUpgrade, setSelectedAuctionForUpgrade] = useState<string | null>(null);

  // Load Razorpay Script
  useEffect(() => {
    const script = document.createElement('script');
    script.src = 'https://checkout.razorpay.com/v1/checkout.js';
    script.async = true;
    script.onload = () => setIsRazorpayLoaded(true);
    document.body.appendChild(script);
    return () => { if (document.body.contains(script)) document.body.removeChild(script); };
  }, []);

  // Fetch Dynamic Plans or fallback to defaults
  useEffect(() => {
      const unsub = db.collection('subscriptionPlans').orderBy('price', 'asc').onSnapshot(snap => {
          if (snap.empty) {
              setDbPlans([
                  { id: 'free', name: 'Free (Demo)', price: 0, teams: 2, features: ['2 Teams Max', 'Standard Overlays'] },
                  { id: 'basic', name: 'Basic Protocol', price: 499, teams: 10, features: ['10 Teams Max', 'OBS Overlays'] },
                  { id: 'premium', name: 'Premium Elite', price: 999, teams: 25, features: ['25 Teams Max', 'Projector Mode'] }
              ]);
          } else {
              setDbPlans(snap.docs.map(d => ({ id: d.id, ...d.data() })));
          }
      });
      return () => unsub();
  }, []);

  const setupListener = () => {
        if (!userProfile?.uid) return () => {};
        setLoading(true);
        setError(null);
        try {
            const unsubscribe = db.collection('auctions')
                .where('createdBy', '==', userProfile.uid)
                .onSnapshot((snapshot) => {
                    const data = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as AuctionSetup));
                    data.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
                    setAuctions(data);
                    setLoading(false);
                }, (error: any) => {
                    setLoading(false);
                    setError("Failed to load auctions: " + error.message);
                });
            return unsubscribe;
        } catch (e: any) {
            setError(e.message);
            setLoading(false);
            return () => {};
        }
  };

  useEffect(() => {
    let unsubscribe: any;
    if (userProfile?.uid) { unsubscribe = setupListener(); }
    return () => { if (unsubscribe) unsubscribe(); };
  }, [userProfile]);

  const handleAuctionSubscription = (auctionId: string, plan: any) => {
      if (!isRazorpayLoaded) return alert("Payment system initializing...");
      if (plan.price === 0) return alert("This auction is already on the Free tier.");

      const options = {
          key: "rzp_test_pnZyMfa3h3mMXR",
          amount: plan.price * 100,
          currency: "INR",
          name: "SM SPORTS",
          description: `License Upgrade: ${plan.name}`,
          handler: async (response: any) => {
              await db.collection('auctions').doc(auctionId).update({
                  isPaid: true,
                  planId: plan.id,
                  totalTeams: plan.teams // Automatically expand team limit to match plan
              });
              alert("Activation Successful! This auction is now upgraded to PRO.");
              setSelectedAuctionForUpgrade(null);
          },
          prefill: { email: userProfile?.email },
          theme: { color: "#16a34a" }
      };
      const rzp = new (window as any).Razorpay(options);
      rzp.open();
  };

  const copyRegLink = (auctionId: string) => {
      const baseUrl = window.location.href.split('#')[0];
      const url = `${baseUrl}#/auction/${auctionId}/register`;
      navigator.clipboard.writeText(url);
      alert("✅ Registration Link Copied!");
  };

  const handleDeleteAuction = async (auctionId: string, title: string) => {
      if (window.confirm(`Delete auction "${title}"?`)) {
          try { await db.collection('auctions').doc(auctionId).delete(); } 
          catch (e: any) { alert("Delete failed: " + e.message); }
      }
  };

  const renderAuctions = () => (
      <div className="space-y-6 animate-fade-in">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <h2 className="text-2xl font-bold text-gray-800 uppercase tracking-tight">Active Registries ({auctions.length})</h2>
              <div className="flex gap-2">
                  <button onClick={() => navigate('/scoring')} className="bg-blue-600 hover:bg-blue-700 text-white font-black py-2 px-6 rounded-xl shadow shadow-blue-900/20 transition-all flex items-center text-[10px] uppercase tracking-widest"><Activity className="w-4 h-4 mr-2" /> Scoring</button>
                  <button onClick={() => navigate('/admin/new')} className="bg-green-600 hover:bg-green-700 text-white font-black py-2 px-6 rounded-xl shadow shadow-green-900/20 transition-all flex items-center text-[10px] uppercase tracking-widest"><Plus className="w-4 h-4 mr-2" /> New Instance</button>
              </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                {loading ? (
                    <div className="p-12 text-center text-gray-500 flex flex-col items-center">
                        <RefreshCw className="animate-spin h-8 w-8 text-green-600 mb-2"/>
                        Syncing registry...
                    </div>
                ) : (
                    <div className="divide-y divide-gray-100">
                        {auctions.length > 0 ? auctions.map((auction) => (
                            <div key={auction.id} className="p-0 hover:bg-gray-50/50 transition-colors group">
                                <div className="p-6 flex flex-col md:flex-row justify-between md:items-center gap-4">
                                    <div className="flex-1 flex items-center gap-4">
                                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black text-white shadow-lg ${auction.isPaid ? 'bg-gradient-to-br from-green-600 to-green-800' : 'bg-gradient-to-br from-gray-400 to-gray-600'}`}>
                                            {auction.isPaid ? <ShieldCheck className="w-6 h-6"/> : <Gavel className="w-6 h-6"/>}
                                        </div>
                                        <div>
                                            <h4 className="font-black text-gray-700 text-lg uppercase tracking-tight">{auction.title}</h4>
                                            <div className="flex items-center gap-3 mt-1">
                                                <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">{auction.sport} • {auction.date}</p>
                                                <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full border ${auction.isPaid ? 'bg-green-50 border-green-200 text-green-600' : 'bg-gray-100 border-gray-200 text-gray-500'}`}>
                                                    {auction.isPaid ? 'Licensed PRO' : 'FREE Instance'}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex flex-wrap items-center gap-2">
                                        {!auction.isPaid && userProfile?.role !== UserRole.SUPER_ADMIN && (
                                            <button 
                                                onClick={() => setSelectedAuctionForUpgrade(selectedAuctionForUpgrade === auction.id ? null : auction.id!)}
                                                className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all flex items-center gap-2 ${selectedAuctionForUpgrade === auction.id ? 'bg-blue-600 text-white border-blue-600' : 'bg-blue-50 text-blue-600 border-blue-100 hover:bg-blue-100'}`}
                                            >
                                                <CreditCard className="w-3 h-3" /> Upgrade
                                            </button>
                                        )}
                                        <button onClick={() => copyRegLink(auction.id!)} className="text-emerald-600 hover:bg-emerald-50 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase border border-emerald-100 flex items-center transition-all"><LinkIcon className="w-3 h-3 mr-1" /> Reg</button>
                                        <button onClick={() => navigate(`/auction/${auction.id}`)} className="bg-white border border-gray-200 text-gray-700 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-100 transition-all">Live</button>
                                        <button onClick={() => navigate(`/admin/auction/${auction.id}/manage`)} className="bg-white border border-gray-200 text-gray-700 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-100 transition-all">Manage</button>
                                        <button onClick={() => handleDeleteAuction(auction.id!, auction.title)} className="text-red-400 hover:text-red-600 p-2 rounded transition-colors"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>

                                {/* Inline Plan Selector - No Popups */}
                                {selectedAuctionForUpgrade === auction.id && (
                                    <div className="bg-blue-50/50 p-6 border-t border-blue-100 animate-slide-up">
                                        <div className="flex items-center gap-3 mb-6">
                                            <div className="bg-blue-600 p-2 rounded-lg text-white shadow-lg shadow-blue-900/20"><Sparkles className="w-4 h-4"/></div>
                                            <div>
                                                <h5 className="font-black text-blue-900 uppercase text-xs tracking-widest">Select Activation Protocol</h5>
                                                <p className="text-[9px] text-blue-400 font-bold uppercase">Payment is specific to this auction instance.</p>
                                            </div>
                                        </div>
                                        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
                                            {dbPlans.filter(p => p.price > 0).map(plan => (
                                                <div key={plan.id} className="bg-white p-5 rounded-2xl border-2 border-white hover:border-blue-300 transition-all shadow-sm flex flex-col group">
                                                    <div className="flex justify-between items-start mb-3">
                                                        <h6 className="font-black text-gray-800 uppercase text-[10px] tracking-widest">{plan.name}</h6>
                                                        <span className="text-blue-600 font-black text-lg">₹{plan.price}</span>
                                                    </div>
                                                    <p className="text-[9px] text-gray-400 font-bold uppercase mb-4 leading-relaxed">Limit: Up to {plan.teams} Teams</p>
                                                    <button 
                                                        onClick={() => handleAuctionSubscription(auction.id!, plan)}
                                                        className="w-full bg-blue-900 hover:bg-black text-white font-black py-2.5 rounded-xl text-[9px] uppercase tracking-widest transition-all active:scale-95 shadow-lg"
                                                    >
                                                        ACTIVATE LICENSE
                                                    </button>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        )) : (
                            <div className="p-20 text-center text-gray-400 italic font-medium uppercase tracking-widest text-xs">No active registries detected in cloud.</div>
                        )}
                    </div>
                )}
          </div>
      </div>
  );

  const renderPlans = () => (
      <div className="animate-fade-in">
          <div className="text-center max-w-2xl mx-auto mb-12">
              <h2 className="text-3xl font-black text-gray-800 uppercase tracking-tighter mb-2">Operational Licensing</h2>
              <p className="text-gray-500 text-sm font-medium">Professional grade features locked to individual auction instances.</p>
