          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {dbPlans.map(plan => (
                  <div key={plan.id} className={`bg-white rounded-3xl p-8 border-2 transition-all relative flex flex-col border-gray-100 hover:shadow-2xl hover:border-blue-100`}>
