                          ))}
                      </div>
                      <div className="bg-gray-50 rounded-2xl p-4 border border-gray-100">
                          <p className="text-[10px] font-black text-gray-400 uppercase text-center mb-0">Select an auction to upgrade from the list above.</p>
                      </div>
                  </div>
