                  { id: 'basic', name: 'Basic Plan', price: 499, teams: 10, features: ['Up to 10 Teams', 'OBS Overlays'] },
                  { id: 'premium', name: 'Premium Plan', price: 999, teams: 25, features: ['Up to 25 Teams', 'Projector Mode'] }
