                                                    <div className="flex items-baseline mb-3">
                                                        <span className="text-blue-600 font-black text-xl">₹{plan.price}</span>
                                                        <span className="text-[8px] text-gray-400 font-bold ml-1">/Auction</span>
                                                    </div>
