              // We still respect server data but based on user prompt, we might want to filter here too
              // However, usually DB data would be updated by super admin. 
              // For the purpose of this request, we show the 5 tiers.
              setDbPlans(snap.docs.map(d => ({ id: d.id, ...d.data() })).filter(p => p.teams <= 15));
          }
      });
      return () => unsub();
