                                                    <Upload className="text-white w-5 h-5"/>
                                                    <input type="file" className="hidden" accept="image/*" onChange={async e => {
                                                        if (e.target.files?.[0]) setRegConfig({...regConfig, bannerUrl: await compressImage(e.target.files[0])});
                                                    }} />
                                                </label>
                                            </div>
                                            <div className="flex-[2] flex flex-col justify-center">
                                                <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest">Banner Logo</p>
                                            </div>
                                        </div>
                                        <div>
                                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Terms & Conditions (One per line)</label>
                                            <textarea 
                                                className="w-full bg-gray-50 border border-gray-200 rounded-xl p-4 text-xs font-bold text-gray-600 min-h-[100px] outline-none focus:bg-white focus:border-blue-500 transition-all"
                                                value={regConfig.terms}
                                                onChange={e => setRegConfig({...regConfig, terms: e.target.value})}
                                            />
                                        </div>
                                    </div>
                                </div>

                                {/* Custom Form Fields */}
                                <div className="mt-12 pt-12 border-t border-gray-100">
                                    <div className="flex flex-col sm:flex-row justify-between items-center mb-8 gap-4">
                                        <h3 className="text-sm font-black text-gray-800 uppercase tracking-widest text-center sm:text-left">Custom Form Fields</h3>
                                        <button onClick={addCustomField} className="w-full sm:w-auto bg-blue-50 text-blue-600 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-blue-100 transition-all">
                                            <ListPlus className="w-4 h-4"/> Add Dynamic Field
                                        </button>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                        {regConfig.customFields.map(field => (
                                            <div key={field.id} className="bg-gray-50/50 border border-gray-100 rounded-[2rem] p-6 relative group hover:bg-white hover:shadow-xl hover:border-blue-100 transition-all">
                                                <button onClick={() => removeCustomField(field.id)} className="absolute -top-3 -right-3 bg-red-500 text-white p-1.5 rounded-full opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-all shadow-lg hover:scale-110"><X className="w-4 h-4"/></button>
                                                <div className="grid grid-cols-2 gap-4">
                                                    <div>
                                                        <label className="block text-[9px] font-black text-gray-300 uppercase tracking-widest mb-1.5">Label</label>
                                                        <input className="w-full bg-white border border-gray-100 rounded-lg px-3 py-2 text-xs font-black uppercase tracking-tighter outline-none focus:border-blue-400" value={field.label} onChange={e => updateField(field.id, 'label', e.target.value.toUpperCase())} placeholder="ENTER FIELD NAME" />
                                                    </div>
                                                    <div>
                                                        <label className="block text-[9px] font-black text-gray-300 uppercase tracking-widest mb-1.5">Type</label>
                                                        <div className="flex flex-wrap gap-1 mt-1">
                                                            {['text', 'number', 'select', 'date'].map(ft => (
                                                                <button
                                                                    key={ft}
                                                                    type="button"
                                                                    onClick={() => updateField(field.id, 'type', ft)}
                                                                    className={`px-2 py-1 rounded text-[8px] font-black uppercase transition-all ${field.type === ft ? 'bg-blue-600 text-white' : 'bg-white border border-gray-200 text-gray-400'}`}
                                                                >
                                                                    {ft}
                                                                </button>
                                                            ))}
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="mt-4 flex items-center justify-between">
                                                    <label className="flex items-center gap-2 cursor-pointer">
                                                        <input type="checkbox" checked={field.required} onChange={e => updateField(field.id, 'required', e.target.checked)} className="accent-blue-600" />
                                                        <span className="text-[9px] font-black text-gray-500 uppercase">Required</span>
                                                    </label>
                                                </div>
                                                {/* Inline Dropdown Options */}
                                                {field.type === 'select' && (
                                                    <div className="mt-4 animate-fade-in">
                                                        <label className="block text-[8px] font-black text-blue-400 uppercase tracking-widest mb-1.5">Dropdown Options (Comma separated)</label>
                                                        <input className="w-full bg-blue-50 border border-blue-100 rounded-lg px-3 py-2 text-[10px] font-bold outline-none" value={(field.options || []).join(',')} onChange={e => updateField(field.id, 'options', e.target.value.split(','))} placeholder="S,M,L,XL,2XL..." />
                                                    </div>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div className="p-10 bg-white border-t border-gray-100 flex justify-center">
                                <button onClick={handleSaveRegistration} className="w-full md:w-auto bg-blue-600 hover:bg-blue-700 text-white font-black py-4 px-16 rounded-2xl shadow-2xl shadow-blue-900/40 text-sm uppercase tracking-[0.3em] flex items-center justify-center gap-3 transition-all active:scale-95 group">
                                    <Save className="w-5 h-5 group-hover:rotate-12 transition-transform" /> Deploy Registration Protocol
                                </button>
                            </div>
                        </div>
                    </div>
                )}

            </main>
        </div>
    );
};

export default AuctionManage;

import React, { useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuction } from '../hooks/useAuction';
import { Plus, Search, Menu, AlertCircle, RefreshCw, Database, Trash2, Cast, Monitor, Activity, UserPlus, Link as LinkIcon, ShieldCheck, CreditCard, Scale, FileText, ChevronRight, CheckCircle, Info, Zap, Crown, Users, Gavel, Sparkles, Shield, Book, HelpCircle, UserPlus2, Layout, Youtube, MessageSquare, Star, Trophy } from 'lucide-react';
import { db } from '../firebase';
import { AuctionSetup, UserPlan, UserRole } from '../types';

const AdminDashboard: React.FC = () => {
  const { userProfile, logout } = useAuction();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [auctions, setAuctions] = useState<(AuctionSetup & { currentTeamCount?: number })[]>([]);
  const [dbPlans, setDbPlans] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'AUCTIONS' | 'PLANS' | 'LEGAL'>('AUCTIONS');
  const [isRazorpayLoaded, setIsRazorpayLoaded] = useState(false);
  const [selectedAuctionForUpgrade, setSelectedAuctionForUpgrade] = useState<string | null>(null);

  const COMMON_FEATURES = [
      { name: 'Online player registration', icon: <UserPlus2 className="w-4 h-4" /> },
      { name: 'Excel Data entry support', icon: <FileText className="w-4 h-4" /> },
      { name: 'Public Auction Page', icon: <Layout className="w-4 h-4" /> },
      { name: 'Auto points calculation', icon: <Zap className="w-4 h-4" /> },
      { name: 'WhatsApp Player Updates', icon: <MessageSquare className="w-4 h-4" /> },
      { name: 'LED/Projector Views', icon: <Monitor className="w-4 h-4" /> },
      { name: 'YouTube Overlays', icon: <Youtube className="w-4 h-4" /> },
  ];

  // Detect auto-upgrade query param
  useEffect(() => {
    const upgradeId = searchParams.get('upgrade');
    if (upgradeId) {
        setSelectedAuctionForUpgrade(upgradeId);
        setActiveTab('AUCTIONS');
    }
  }, [searchParams]);

  // Load Razorpay Script
  useEffect(() => {
    const script = document.createElement('script');
    script.src = 'https://checkout.razorpay.com/v1/checkout.js';
    script.async = true;
    script.onload = () => setIsRazorpayLoaded(true);
    document.body.appendChild(script);
    return () => { if (document.body.contains(script)) document.body.removeChild(script); };
  }, []);

  // Fetch Dynamic Plans or fallback to defaults matching the requested image (limited to 15 teams)
  useEffect(() => {
      const unsub = db.collection('subscriptionPlans').orderBy('price', 'asc').onSnapshot(snap => {
          if (snap.empty) {
              setDbPlans([
                  { id: 'plan_1', name: 'Plan 1 - Free', price: 0, teams: 2 },
                  { id: 'plan_2', name: 'Plan 2', price: 3000, teams: 4 },
                  { id: 'plan_3', name: 'Plan 3', price: 4000, teams: 6 },
                  { id: 'plan_4', name: 'Plan 4', price: 5000, teams: 10 },
                  { id: 'plan_5', name: 'Plan 5', price: 6000, teams: 15 },
              ]);
          } else {
              setDbPlans(snap.docs.map(d => ({ id: d.id, ...d.data() })).filter(p => p.teams <= 15));
          }
      });
      return () => unsub();
  }, []);

  const setupListener = () => {
        if (!userProfile?.uid) return () => {};
        setLoading(true);
        setError(null);
        try {
            const unsubscribe = db.collection('auctions')
                .where('createdBy', '==', userProfile.uid)
                .onSnapshot(async (snapshot) => {
                    const auctionsData = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as AuctionSetup));

                    // Fetch team counts for each auction to validate plans
                    const auctionsWithCounts = await Promise.all(auctionsData.map(async (a) => {
                        const teamsSnap = await db.collection('auctions').doc(a.id).collection('teams').get();
                        return { ...a, currentTeamCount: teamsSnap.size };
                    }));

                    auctionsWithCounts.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
                    setAuctions(auctionsWithCounts);
                    setLoading(false);
                }, (error: any) => {
                    setLoading(false);
                    setError("Failed to load auctions: " + error.message);
                });
            return unsubscribe;
        } catch (e: any) {
            setError(e.message);
            setLoading(false);
            return () => {};
        }
  };

  useEffect(() => {
    let unsubscribe: any;
    if (userProfile?.uid) { unsubscribe = setupListener(); }
    return () => { if (unsubscribe) unsubscribe(); };
  }, [userProfile]);

  const handleAuctionSubscription = (auctionId: string, plan: any) => {
      if (!isRazorpayLoaded) return alert("Payment system is loading...");
      if (plan.price === 0) return alert("This auction is already on the Free Plan.");

      const options = {
          key: "rzp_test_pnZyMfa3h3mMXR",
          amount: plan.price * 100,
          currency: "INR",
          name: "SM SPORTS",
          description: `Upgrade Auction: ${plan.name}`,
          handler: async (response: any) => {
              await db.collection('auctions').doc(auctionId).update({
                  isPaid: true,
                  planId: plan.id,
                  totalTeams: plan.teams 
              });
              alert("Success! Your auction has been upgraded.");
              setSelectedAuctionForUpgrade(null);
          },
          prefill: { email: userProfile?.email },
          theme: { color: "#16a34a" }
      };
      const rzp = new (window as any).Razorpay(options);
      rzp.open();
  };

  const copyRegLink = (auctionId: string) => {
      const baseUrl = window.location.href.split('#')[0];
      const url = `${baseUrl}#/auction/${auctionId}/register`;
      navigator.clipboard.writeText(url);
      alert("✅ Registration link copied!");
  };

  const handleDeleteAuction = async (auctionId: string, title: string) => {
      if (window.confirm(`Delete auction "${title}"?`)) {
          try { await db.collection('auctions').doc(auctionId).delete(); } 
          catch (e: any) { alert("Delete failed: " + e.message); }
      }
  };

  const renderAuctions = () => (
      <div className="space-y-6 animate-fade-in">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <h2 className="text-2xl font-bold text-gray-800 tracking-tight">My Auctions ({auctions.length})</h2>
              <div className="flex gap-2">
                  <button onClick={() => navigate('/scoring')} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-6 rounded-xl shadow shadow-blue-900/10 transition-all flex items-center text-xs"><Activity className="w-4 h-4 mr-2" /> SCORING</button>
                  <button onClick={() => navigate('/admin/new')} className="bg-green-600 hover:bg-green-700 text-white font-bold py-2 px-6 rounded-xl shadow shadow-green-900/10 transition-all flex items-center text-xs"><Plus className="w-4 h-4 mr-2" /> NEW AUCTION</button>
              </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                {loading ? (
                    <div className="p-12 text-center text-gray-500 flex flex-col items-center">
                        <RefreshCw className="animate-spin h-8 w-8 text-green-600 mb-2"/>
                        Loading auctions...
                    </div>
                ) : (
                    <div className="divide-y divide-gray-100">
                        {auctions.length > 0 ? auctions.map((auction) => (
                            <div key={auction.id} id={`auction-${auction.id}`} className={`p-0 transition-colors group ${selectedAuctionForUpgrade === auction.id ? 'bg-blue-50/20' : 'hover:bg-gray-50/50'}`}>
                                <div className="p-6 flex flex-col md:flex-row justify-between md:items-center gap-4">
                                    <div className="flex-1 flex items-center gap-4">
                                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-bold text-white shadow-lg ${auction.isPaid ? 'bg-gradient-to-br from-green-500 to-green-700' : 'bg-gradient-to-br from-gray-400 to-gray-500'}`}>
                                            {auction.isPaid ? <ShieldCheck className="w-6 h-6"/> : <Gavel className="w-6 h-6"/>}
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-gray-800 text-lg">{auction.title}</h4>
                                            <div className="flex items-center gap-3 mt-1">
                                                <p className="text-xs text-gray-400 font-semibold">{auction.sport} • {auction.date}</p>
                                                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${auction.isPaid ? 'bg-green-50 border-green-200 text-green-600' : 'bg-gray-100 border-gray-200 text-gray-500'}`}>
                                                    {auction.isPaid ? 'Paid Version' : 'Free Version'}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex flex-wrap items-center gap-2">
                                        {!auction.isPaid && userProfile?.role !== UserRole.SUPER_ADMIN && (
                                            <button 
                                                onClick={() => setSelectedAuctionForUpgrade(selectedAuctionForUpgrade === auction.id ? null : auction.id!)}
                                                className={`px-4 py-1.5 rounded-xl text-xs font-bold border transition-all flex items-center gap-2 ${selectedAuctionForUpgrade === auction.id ? 'bg-blue-600 text-white border-blue-600' : 'bg-blue-50 text-blue-600 border-blue-100 hover:bg-blue-100'}`}
                                            >
                                                <CreditCard className="w-3 h-3" /> Upgrade
                                            </button>
