        const from = Number(newSlab.from);
        const inc = Number(newSlab.increment);
        if (from >= 0 && inc > 0) {
            setSlabs([...slabs, { from, increment: inc }]);
            setNewSlab({ from: '', increment: '' });
        }
    };

