        e.preventDefault();
        if (!id) return;
        const catData = { 
            name: editItem.name, 
            basePrice: Number(editItem.basePrice), 
            minPerTeam: Number(editItem.minPerTeam || 0),
            maxPerTeam: Number(editItem.maxPerTeam), 
            bidIncrement: Number(editItem.bidIncrement || settingsForm.bidIncrement),
