                                        </div>
                                        <div>
                                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Sport</label>
                                            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
                                                {['Cricket', 'Football', 'Kabaddi'].map(s => (
                                                    <button 
